            heights = {a["id"]: float(a.get("heightM") or 1.7) for a in scene_i.get("actors") or []}
            names = {a["id"]: a.get("name") for a in scene_i.get("actors") or []}
            for cut in scene_i.get("timeline") or []:
                cid = cut["cutId"]
