            if err_of(start(pid_a, {"confirmUsd": usd_a}))[:2] != (409, "RealRunning"):
                bad.append("(lr-a) 진행 중 다시 시작이 409 RealRunning 이 아닙니다")
            view_run = genmod.gen_view(owner, pid_a, env.plan(pid_a))
