            m4 = client.get(f"/api/vnew/p/prj_edt_cache/edit/media/{mid_c1}").get_json() or {}
            expect("edt-i", [m4.get("generated"), len(env.films)], [True, 3], "원본이 다른 캐시는 다시 만든다")
            long_key = _edt_key("prj_edt_long", "c1-webtoon-1")
