            state["rc"], state["stderr"] = 0, ""
            expect("edt-j", bad_args, ["편집 구간 값이 올바르지 않습니다."] * 6 + ["자를 클립이 없습니다.", "클립을 편집하지 못했습니다"],
                   "edit_segment 값 검사 6경우·원본 없음·ffmpeg 실패")
            seg2 = os.path.join(jdir, "it's.mp4")
