def check_vnew_conti_images_120() -> None:
    """지시서 120 — ③ 콘티가 웹툰 그림을 직접 보고 샷 구도·그려진 기호를 정한다. 가짜 LLM·가짜 저장소·유료 호출 0.

    (ci-a) 스키마·규칙: EMIT_CONTI 새 선택 필드 6개(enum·상한 = fx.py 상수)·required 그대로, CONTI_SYSTEM 라벨·샷 크기·기호 목록
    (ci-b) 블록(run_conti): 켬 → 글 1 + "Panel N of M:" 라벨 바로 뒤 이미지(타일 수만큼, N = 0부터 = entries.panels 번호),
           끔 → [글 하나] 바이트 같음·타일 읽기 0
    (ci-c) 저장: sourcePanel(컷 panels 안·보낸 장수 미만)·shotSize(정리·목록 밖 버림)·fxDrawn(목록 밖·중복 버림·5개)·fx 비면 fxDrawn 앞 2개·
           mood 60/80자, 끔이면 콘티의 기호 필드를 쓰지 않음, update_conti 정리(_clean_conti_shot)·옛 컷 그대로
    (ci-d) 채우기 건너뛰기: 콘티가 모든 컷을 채움 → _analyze_fx 0회, 비었음 → 1회. 변형 1회: _conti_fx_item 이 빈 값도 채운 것으로 보면 잡힌다
    (ci-e) 그림 호출 실패 → 로그 1줄 + 글만 1회 다시 → 성공
    (ci-f) 화면(node): SHOT_SIZE_KO 7개(서버 SHOT_SIZES 순서)·contiShotHead(옛 컷 "")·카드 머리·대표 썸네일 강조
    """
    sys.path.insert(0, str(ROOT / "app"))
    import logging as _logging  # noqa: PLC0415
    import traceback as _tb  # noqa: PLC0415

    bad: list[str] = []
    seen: set[str] = set()

    def expect(group: str, got, want, what: str) -> None:
        seen.add(group)
        if got != want:
            bad.append(f"({group}) {what}\n      결과 {got!r}\n      기대 {want!r}")

    try:
        from src.vnew import fx as fxmod  # noqa: PLC0415
        from src.vnew import plan as planmod  # noqa: PLC0415
        from src.vnew import prompts as prmod  # noqa: PLC0415

        # ================= (ci-a) 스키마·규칙 =================
        item = prmod.EMIT_CONTI["inputSchema"]["json"]["properties"]["cuts"]["items"]
        props = item["properties"]
        expect("ci-a", [item["required"], props.get("sourcePanel"), props.get("shotSize"),
                        props.get("fxDrawn", {}).get("maxItems"), props.get("fxDrawn", {}).get("items", {}).get("enum"),
                        props.get("fxSuggest", {}).get("maxItems"), props.get("fxSuggest", {}).get("items", {}).get("enum"),
                        props.get("moodKo"), props.get("moodEn"), "fx" in props],
               [["id", "seconds", "shotKo", "promptEn"], {"type": "integer"},
                {"type": "string", "enum": ["wide", "medium", "closeup", "extreme_closeup", "over_shoulder", "profile", "insert"]},
                fxmod.DRAWN_MAX, list(fxmod.FX_KEYS), fxmod.FX_MAX, list(fxmod.FX_KEYS),
                {"type": "string", "maxLength": fxmod.MOOD_KO_MAX}, {"type": "string", "maxLength": fxmod.MOOD_EN_MAX}, False],
               "EMIT_CONTI 새 선택 필드(sourcePanel·shotSize·fxDrawn ≤5·fxSuggest ≤2·moodKo ≤60·moodEn ≤80, fx.py 상수)·required 그대로")
        system = prmod.CONTI_SYSTEM
        expect("ci-a", ['"Panel N of M:"' in system, all(s in system for s in prmod.SHOT_SIZES), " | ".join(fxmod.FX_KEYS) in system,
                        "sourcePanel" in system and "fxDrawn" in system and "fxSuggest" in system,
                        system.rstrip().endswith("Answer only with the emit_conti tool.")],
               [True, True, True, True, True], "CONTI_SYSTEM: 라벨 뜻·샷 크기 7개·기호 목록·새 필드·끝 문장")

        # ================= 가짜 저장소·LLM =================
        def base_plan() -> dict:
            return {"planId": "plan_c", "revision": 1, "input": {"order": ["f1"], "totalSeconds": 15},
                    "task": {"name": "conti", "status": "running", "startedAt": None, "id": "t1"},
                    "script": {"status": "ready", "setting": {"locationKo": "교실", "locationEn": "classroom"}, "entries": [
                        {"id": "e1", "panels": [0], "speaker": "민지", "lineKo": "왜?", "situationKo": "본다", "locationEn": "classroom"},
                        {"id": "e2", "panels": [1], "speaker": "준호", "lineKo": "응", "situationKo": "웃는다", "locationEn": "classroom"},
                        {"id": "e3", "panels": [2], "speaker": "민지", "lineKo": "", "situationKo": "손", "locationEn": "classroom"}]}}

        def cuts_payload(with_fx: bool) -> dict:
            rows = [
                {"id": "c1", "seconds": 3, "panels": [0, 1], "shotKo": "민지 얼굴", "promptEn": "p1", "sourcePanel": 1, "shotSize": "closeup",
                 "fxDrawn": ["blush lines", "horns", "Sweat  Drop", "blush lines", "tear streams", "speed lines", "pink sparkle background"],
                 "moodKo": "가" * 100, "moodEn": "a" * 120},
                {"id": "c2", "seconds": 3, "panels": [1], "shotKo": "준호", "promptEn": "p2", "sourcePanel": 9, "shotSize": "zoom",
                 "fxSuggest": ["speed lines", "horns"], "moodKo": "긴장", "moodEn": "tense"},
                {"id": "c3", "seconds": 3, "panels": [2], "shotKo": "눈", "promptEn": "p3", "sourcePanel": 2, "shotSize": "Extreme Closeup",
                 "moodKo": "평온", "moodEn": "calm"},
                {"id": "c4", "seconds": 3, "panels": [2], "shotKo": "울음", "promptEn": "p4", "sourcePanel": True, "shotSize": "wide",
                 "fxDrawn": ["tear streams"], "moodKo": "슬픔", "moodEn": "sad"},
                {"id": "c5", "seconds": 3, "panels": [0], "shotKo": "손", "promptEn": "p5", "shotSize": "insert", "moodKo": "손", "moodEn": "hands"},
            ]
            if not with_fx:
                for row in rows:
                    for key in fxmod.FX_FIELDS:
                        row.pop(key, None)
            return {"cuts": rows}

        saved: dict = {}
        conti_calls: list = []
        fx_calls: list = []
        tile_calls: list = []
        state = {"payload": None, "fail_images": False}
        names = ("load_plan", "mutate_plan", "ordered_tiles", "_analyze_conti", "_analyze_fx", "_charge",
                 "_sync_locations_after_conti", "_unapprove_previz_after_conti", "_max_segment_seconds", "_conti_fx_item")
        orig = {n: getattr(planmod, n) for n in names}

        def fake_conti(blocks, *, model):
            conti_calls.append(blocks)
            if state["fail_images"] and any("image" in b for b in blocks):
                raise RuntimeError("ValidationException: too many images")
            return json.loads(json.dumps(state["payload"])), {"model": "m-c"}

        planmod.load_plan = lambda owner, pid: (saved, "etag")
        planmod.mutate_plan = lambda owner, pid, mutator, **kw: (saved, mutator(saved))
        planmod.ordered_tiles = lambda owner, pid, order: (tile_calls.append(list(order)) or ([b"t0", b"t1", b"t2"], 3, 3))
        planmod._analyze_conti = fake_conti  # noqa: SLF001
        planmod._analyze_fx = lambda blocks, *, model: (fx_calls.append(blocks) or ({"cuts": []}, {"model": "m-f"}))  # noqa: SLF001
        planmod._charge = lambda *a, **kw: None  # noqa: SLF001
        planmod._sync_locations_after_conti = lambda owner, pid: None  # noqa: SLF001
        planmod._unapprove_previz_after_conti = lambda owner, pid: None  # noqa: SLF001
        planmod._max_segment_seconds = lambda video_model: 15  # noqa: SLF001

        fallback_logs: list = []

        class _Grab(_logging.Handler):
            def emit(self, record):
                if str(record.msg).startswith("vnew.conti.images_fallback"):
                    fallback_logs.append(record.getMessage())

        grab = _Grab()
        _logging.getLogger("vpoc").addHandler(grab)

        def run(with_fx: bool, *, images: bool = True, fail_images: bool = False) -> dict:
            saved.clear()
            saved.update(base_plan())
            conti_calls.clear()
            fx_calls.clear()
            tile_calls.clear()
            fallback_logs.clear()
            state["payload"] = cuts_payload(with_fx)
            state["fail_images"] = fail_images
            with _pin_vnew(VNEW_FX=True, VNEW_CONTI_IMAGES=images):
                planmod.run_conti("o", "p", "t1")
            return saved

        def prompt_text() -> str:
            plan0 = base_plan()
            return planmod._conti_prompt(plan0["script"], 15, "", "(연결된 캐릭터 없음)")  # noqa: SLF001

        try:
            # ================= (ci-b) 블록 =================
            run(True)
            blocks = conti_calls[0] if conti_calls else []
            images = [i for i, b in enumerate(blocks) if "image" in b]
            labels = [blocks[i - 1].get("text") for i in images]
            expect("ci-b", [len(conti_calls), blocks[:1] == [{"text": prompt_text()}], len(images), labels,
                            [blocks[i]["image"]["source"]["bytes"] for i in images], tile_calls],
                   [1, True, 3, ["Panel 0 of 3:", "Panel 1 of 3:", "Panel 2 of 3:"], [b"t0", b"t1", b"t2"], [["f1"]]],
                   "켬: 대본 글 블록 맨 앞·이미지 수 = 타일 수·각 이미지 바로 앞 \"Panel N of M:\"(N 0부터 = entries.panels)·대본과 같은 ordered_tiles")

            cuts_on = {c["id"]: c for c in saved["conti"]["cuts"]}
            fx_on_calls = len(fx_calls)
            fill_on = dict(saved.get("fxFill") or {})

            run(True, images=False)
            off_blocks = conti_calls[0] if conti_calls else []
            expect("ci-b", [json.dumps(off_blocks, ensure_ascii=False) == json.dumps([{"text": prompt_text()}], ensure_ascii=False),
                            tile_calls, len(conti_calls), len(fx_calls)],
                   [True, [["f1"]], 1, 1], "끔: 블록 = [글 하나](바이트 같음·이미지 0)·타일 읽기는 지금처럼 채우기 1번뿐")
            cuts_off = saved["conti"]["cuts"]

            # ================= (ci-c) 저장 =================
            c1, c2, c3, c4, c5 = (cuts_on.get(k, {}) for k in ("c1", "c2", "c3", "c4", "c5"))
            expect("ci-c", [c1.get("sourcePanel"), c1.get("shotSize"), c1.get("fxDrawn"), c1.get("fxSuggest"), c1.get("fx"),
                            len(c1.get("moodKo", "")), len(c1.get("moodEn", ""))],
                   [1, "closeup", ["blush lines", "sweat drop", "tear streams", "speed lines", "pink sparkle background"],
                    ["blush lines", "sweat drop"], ["blush lines", "sweat drop"], fxmod.MOOD_KO_MAX, fxmod.MOOD_EN_MAX],
                   "c1: 대표 패널·샷 크기·fxDrawn(목록 밖·중복 버림·5개 상한)·fx 비면 fxDrawn 앞 2개·mood 60/80자")
            expect("ci-c", [["sourcePanel" in c2, "shotSize" in c2, c2.get("fxSuggest"), c2.get("fx"), c2.get("fxDrawn")],
                            [c3.get("sourcePanel"), c3.get("shotSize"), c3.get("fxSuggest"), c3.get("fx")],
                            ["sourcePanel" in c4, c4.get("shotSize"), c4.get("fx")], [c5.get("shotSize"), "sourcePanel" in c5]],
                   [[False, False, ["speed lines"], [], []], [2, "extreme_closeup", [], []], [False, "wide", ["tear streams"]], ["insert", False]],
                   "c2 패널 밖 sourcePanel·목록 밖 shotSize 버림·추천만(그려진 것 없으면 fx 빈 값), c3 shotSize 정리, c4 bool sourcePanel 버림, c5 키 없음")
            expect("ci-c", [[any(k in c for k in fxmod.FX_FIELDS) for c in cuts_off], [c.get("shotSize") for c in cuts_off]],
                   [[False] * 5, ["closeup", None, "extreme_closeup", "wide", "insert"]],
                   "끔(그림 안 봄): 콘티의 기호·분위기는 쓰지 않음(채우기에 맡김)·샷 크기만 둠")
            kept = {"panels": [0, 1], "sourcePanel": 1, "shotSize": "Over Shoulder"}
            dropped = {"panels": [0], "sourcePanel": 3, "shotSize": "zoom"}
            old = {"id": "c1", "panels": [0], "shotKo": "옛 컷"}
            old_copy = dict(old)
            for cut in (kept, dropped, old):
                planmod._clean_conti_shot(cut)  # noqa: SLF001
            expect("ci-c", [kept, dropped, old == old_copy], [{"panels": [0, 1], "sourcePanel": 1, "shotSize": "over_shoulder"}, {"panels": [0]}, True],
                   "update_conti 정리: 맞는 값 정리·맞지 않는 값 키째 뺌·옛 컷(키 없음) 그대로")

            # ================= (ci-d) 채우기 건너뛰기 =================
            run(False)
            empty_calls = len(fx_calls)
            expect("ci-d", [fx_on_calls, fill_on.get("status"), fill_on.get("filled"), empty_calls, saved.get("fxFill", {}).get("status")],
                   [0, "ready", 5, 1, "ready"], "콘티가 모든 컷을 채움 → _analyze_fx 0회(fxFill ready·filled 5), 비었음 → 1회")

            def mutant(cut_id, item):
                row = orig["_conti_fx_item"](cut_id, item)
                return row or {"id": cut_id, "drawnFx": [], "fxSuggest": [], "fx": [], "moodKo": "", "moodEn": ""}

            planmod._conti_fx_item = mutant  # noqa: SLF001
            try:
                run(False)
                caught = len(fx_calls) != 1
            finally:
                planmod._conti_fx_item = orig["_conti_fx_item"]  # noqa: SLF001
            expect("ci-d", caught, True, "변형(빈 값도 채운 것으로 봄)이면 '비었음 → 1회' 검사가 잡는다")

            # ================= (ci-e) 그림 실패 → 글만 =================
            run(True, fail_images=True)
            expect("ci-e", [len(conti_calls), sum(1 for b in conti_calls[0] if "image" in b) if conti_calls else -1,
                            conti_calls[1] if len(conti_calls) > 1 else None, saved["conti"].get("status"), len(saved["conti"].get("cuts") or []),
                            len(fallback_logs), any("fxSuggest" in c for c in saved["conti"]["cuts"]), len(fx_calls)],
                   [2, 3, [{"text": prompt_text()}], "ready", 5, 1, False, 1],
                   "그림 호출 실패 → 로그 1줄·글만 1회 다시 → 콘티 ready, 그 콘티의 기호는 믿지 않고 채우기 1회")
        finally:
            for n, f in orig.items():
                setattr(planmod, n, f)
            _logging.getLogger("vpoc").removeHandler(grab)
    except Exception as exc:  # noqa: BLE001
        bad.append("검사 중 예외: " + repr(exc) + "\n" + _tb.format_exc()[:1500])

    # ================= (ci-f) 화면(node) =================
    node = shutil.which("node")
    vjs = (PUBLIC / "vnew.js").read_text(encoding="utf-8")
    css = (PUBLIC / "vnew.css").read_text(encoding="utf-8")
    code, problems = _edu_code(vjs, _CI120_SLICE)
    bad.extend(p.replace("(edu-a)", "(ci-f)") for p in problems)
    expect("ci-f", ['if (shotHead) head.appendChild(el("span", "vnew-cut-shot", shotHead));' in vjs,
                    'el("img", "vnew-cut-thumb" + (sourcePanel !== null ? " is-source" : ""))' in vjs,
                    ".vnew-cut-thumb.is-source" in css, ".vnew-cut-shot" in css],
           [True, True, True, True], "카드 머리 글(값 있을 때만)·대표 패널 썸네일 테두리 강조")
    if node and not problems:
        got, err = _lr_run_node(node, code + _CI120_NODE, "ci120_f_")
        if err:
            bad.append(f"(ci-f) node 실행 실패: {err}")
        else:
            expect("ci-f", got, {"keys": ["wide", "medium", "closeup", "extreme_closeup", "over_shoulder", "profile", "insert"],
                                 "names": ["와이드", "미디엄", "클로즈업", "익스트림 클로즈업", "어깨 너머", "옆모습", "인서트"],
                                 "head": ["", "", "패널 2 · 클로즈업", "패널 0", "", "", "인서트", "어깨 너머"]},
                   "SHOT_SIZE_KO 7개(서버 순서)·contiShotHead: 옛 컷 ''·값 있는 것만·모르는 값·문자열·음수·소수 버림")
    elif not node:
        warn("node 가 없어 ci-f(화면)를 건너뜁니다")

    missing = [g for g in ("ci-a", "ci-b", "ci-c", "ci-d", "ci-e", "ci-f") if g not in seen]
    if missing and not bad:
        bad.append(f"검사하지 못한 묶음: {missing}")
    if bad:
        for item in bad:
            fail("vnew 콘티 그림 보기(지시서 120) " + item)
    else:
        ok("vnew 콘티 그림 보기(지시서 120) 검사 (ci-a)스키마·규칙 (ci-b)블록 켬·끔 (ci-c)저장 정리·끔·사용자 저장 "
           "(ci-d)채우기 0/1회·변형 1회 (ci-e)그림 실패 → 글만 (ci-f)화면")


# ---------------------------------------------------------------- 작업 123 — ⑤ 통 테이크 실사·애니(웹툰) 처음부터 함께
#
# 서버: 실제 라우트(POST /generate)·start_generate·드라이버 한 순회(_drive_previz_pass)·start_real 을 _LrEnv 의 가짜 fal·원장으로
# 돌린다(start_real 은 호출 수를 세는 감싸개). 화면: lr-n 구역 + 095 확인창 구역을 node 가짜 DOM 에서 돌린다. 유료·네트워크 0.
_TB123_NODE_CASES = r"""
var TB_EST = { mode: "previz-take", totalUsd: 3.08, realUsd: 3.08, realBlock: "", takes: [{ id: "take1", seconds: 15 }] };
function confirmOf(est) {
  closeAll(); reset();
  state.plan = { previz: {}, features: { fx: true }, gen: { status: "none", estimate: est } };
  openGenerateConfirm(showError, {});
  var scrim = document.body.children[0];
  return {
    boxes: byTag(scrim, "input"),
    view: function () {
      return [byTag(scrim, "input").map(function (b) { return [b.type, b.checked, b.disabled]; }),
              byClass(scrim, "vnew-gen-style").map(function (l) { return [l.textContent, l.className, l.title]; }),
              (byClass(scrim, "vnew-gen-cost")[0] || {}).textContent];
    },
    ok: function () { byText(scrim, "button", "만들기 시작").fire("click"); return calls[calls.length - 1]; }
  };
}
async function run() {
  var c = confirmOf(TB_EST);
  out.both = c.view(); out.bothBody = c.ok(); await tick();
  c = confirmOf(TB_EST);
  c.boxes[1].checked = false; c.boxes[1].fire("change");
  out.webOnly = [c.view()[2], c.ok()]; await tick();
  c = confirmOf({ mode: "previz-take", totalUsd: 3.08, realUsd: 3.08, realBlock: "실사 버전 기능이 꺼져 있습니다.", takes: [{ id: "take1", seconds: 15 }] });
  out.blocked = c.view().concat([c.ok()]); await tick();
  c = confirmOf({ mode: "previz", totalUsd: 4, segments: [{ id: "s1" }] });
  out.cut = [c.boxes.length, c.view()[2], c.ok()]; await tick();
  closeAll();
  var auto = { confirmUsd: 3.08, audio: true, at: "t", startedAt: null, error: null };
  var pending = { genId: "g1", mode: "previz-take", status: "running", realEnabled: true, realRun: null, realHistory: [], canStartReal: false,
                  realBlock: "웹툰 통 테이크가 끝난 뒤에 실사 버전을 만들 수 있습니다.", realEstimate: { usd: 3.08 }, autoReal: auto,
                  finalWebtoon: { status: "waiting" }, finalReal: { status: "skipped" }, units: [] };
  var pv = colView(realCol(pending));
  out.pending = [pv.p, pv.buttons];
  var failed = Object.assign({}, pending, { status: "done", canStartReal: true, realBlock: "",
                                           autoReal: Object.assign({}, auto, { startedAt: "t", error: "x" }),
                                           finalWebtoon: { status: "done", videoUrl: "https://signed.example/fw.mp4" } });
  var fv = colView(realCol(failed));
  out.failed = [fv.p, fv.buttons];
  out.heads = byTag(finalResults(failed, showError), "h2").map(function (n) { return n.textContent; });
  out.sound = takeCompareSoundLabel("webtoon");
  console.log(JSON.stringify(out));
}
run().catch(function (e) { console.error(String((e && e.stack) || e)); process.exit(1); });
"""


def check_vnew_take_both_123() -> None:
    """작업 123 — ⑤ 통 테이크에서 실사·애니(웹툰)를 처음부터 함께(styles·autoReal·자동 시작·화면). 유료 호출 0.

    (tb-a) styles 생략: autoReal 없음·estimate 그대로(실사 0)·보기 estimate.realUsd = real_estimate·realBlock "", 실사 시작 0
    (tb-b) ["webtoon","real"]: 웹툰 금액만 409 CostMismatch, 모양 틀림 400 BadStyles(gen 없음), 합 → 202·autoReal 저장·보기
    (tb-c) 웹툰이 끝난 순회에 실사 회차 1개(start_real 1번·startedAt·"work"), 실사 원장 1번, 끝난 뒤 순회 0번
    (tb-d) 웹툰 실패(partial) → autoReal.error, 다시 시도 → error 지움·done 뒤 실사 1번 자동 시작(163), 취소 → 시작 0·error,
           자동 시작 거절 → error·canStartReal(버튼)
    (tb-e) 끔·컷 단위 + "real" → 400(gen 없음), 변형(_wants_real 이 styles 무시)을 잡음
    (tb-f) 화면: node --check, 확인창 체크 2개·합계 문구·보낸 본문·흐림+title, 컷 단위 그대로, 자동 시작 안내, "애니(웹툰)" 이름
    """
    sys.path.insert(0, str(ROOT / "app"))
    import traceback as _tb  # noqa: PLC0415

    from src.vnew import generate as genmod  # noqa: PLC0415
    from src.vpoc.errors import VpocError  # noqa: PLC0415

    bad: list[str] = []
    seen: set[str] = set()
    owner = "tester"
    seg = [{"id": "s1", "cutIds": ["c1"], "seconds": 15}]
    both = ["webtoon", "real"]
    logs = _LogCapture()
    try:
        with _guard_real_llm() as real_calls, logs, _LrEnv(owner) as env, _pin_vnew(
                VNEW_FX=True, VNEW_CASTING=True, VNEW_TAKE_REAL=True, VNEW_GEN_PARALLEL=2, POLL_INTERVAL_S=0,
                VNEW_TAKE_AUDIO=True, VNEW_TAKE_RESOLUTION="480p", VNEW_PREPARE_STALE_S=300):
            client = env.client()
            starts: list[str] = []
            fail_start: list[str] = []
            real_start = genmod.start_real

            def counting(*args, **kwargs):
                starts.append(args[1])
                if fail_start:
                    raise VpocError("vnew.generate.real", "CharacterRealMissing", fail_start.pop(), 409)
                return real_start(*args, **kwargs)

            env.set(genmod, "start_real", counting)

            def post(pid: str, body: dict) -> tuple[int, str]:
                resp = client.post(f"/api/vnew/p/{pid}/generate", json=body)
                return resp.status_code, str(((resp.get_json() or {}).get("error") or {}).get("type") or "")

            def est_view(pid: str) -> dict:
                return genmod.gen_view(owner, pid, env.plan(pid))["estimate"]

            def fresh(pid: str) -> tuple[dict, float]:
                env.make_plan(pid, seg)
                est = est_view(pid)
                return est, round(est["totalUsd"] + est["realUsd"], 2)

            def one_pass(pid: str):
                return genmod._drive_previz_pass(owner, pid, env.gen(pid)["genId"])  # noqa: SLF001

            # ================= (tb-a) styles 생략 =================
            est_a, _ = fresh("prj_tb_a")
            raw_a = genmod.estimate(env.plan("prj_tb_a"))
            code_a = post("prj_tb_a", {"confirmUsd": raw_a["totalUsd"]})
            g_a = env.gen("prj_tb_a")
            if code_a != (202, "") or "autoReal" in g_a or raw_a.get("realUsd") != 0.0 or est_a["totalUsd"] != raw_a["totalUsd"] \
                    or est_a.get("realUsd") != genmod.real_estimate(g_a)["usd"] or not est_a["realUsd"] > 0 \
                    or est_a.get("realBlock") != "" or genmod.gen_view(owner, "prj_tb_a", env.plan("prj_tb_a")).get("autoReal") is not None:
                bad.append(f"(tb-a) styles 생략이 지금과 다르거나 보기 견적이 다릅니다: {code_a} {est_a} {g_a.get('autoReal')}")
            if env.drive("prj_tb_a").get("realRun") or starts:
                bad.append("(tb-a) styles 생략인데 실사가 시작됐습니다")
            seen.add("tb-a")

            # ================= (tb-b) 합계·모양 =================
            pid_b = "prj_tb_b"
            est_b, total_b = fresh(pid_b)
            codes_b = [post(pid_b, {"confirmUsd": est_b["totalUsd"], "styles": both}),
                       post(pid_b, {"confirmUsd": total_b, "styles": ["real"]}),
                       post(pid_b, {"confirmUsd": total_b, "styles": "webtoon,real"}),
                       post(pid_b, {"confirmUsd": total_b, "styles": ["webtoon", "webtoon"]})]
            no_gen_b = not env.gen(pid_b)
            code_b = post(pid_b, {"confirmUsd": total_b, "styles": both})
            auto_b = env.gen(pid_b).get("autoReal") or {}
            view_auto_b = genmod.gen_view(owner, pid_b, env.plan(pid_b)).get("autoReal") or {}
            if codes_b != [(409, "CostMismatch")] + [(400, "BadStyles")] * 3 or not no_gen_b or code_b != (202, "") \
                    or auto_b.get("confirmUsd") != est_b["realUsd"] or auto_b.get("audio") is not True or not auto_b.get("at") \
                    or auto_b.get("startedAt") or view_auto_b.get("confirmUsd") != est_b["realUsd"] or starts:
                bad.append(f"(tb-b) 합계 409·모양 400·autoReal 저장이 다릅니다: {codes_b} {code_b} {auto_b}")
            seen.add("tb-b")

            # ================= (tb-c) 자동 시작 1번 =================
            led0 = len(env.ledger)
            hit = None
            for _ in range(10):
                before = env.gen(pid_b)
                web_done = all((u.get("webtoon") or {}).get("status") == "completed" for u in before.get("units") or [])
                res = one_pass(pid_b)
                if starts:
                    g = env.gen(pid_b)
                    hit = [web_done, res, (g.get("realRun") or {}).get("n"), len(starts),
                           bool((g.get("autoReal") or {}).get("startedAt")), g.get("status")]
                    break
            led1, req1 = len(env.ledger), len(env.requests)
            g_c = env.drive(pid_b)
            real_charges = [e for e in env.ledger[led1:] if e.get("kind") == "video"]
            web_charges = [e for e in env.ledger[led0:led1] if e.get("kind") == "video"]
            led2, req2 = len(env.ledger), len(env.requests)
            res_after = one_pass(pid_b)
            if hit != [True, "work", 1, 1, True, "running"] or len(web_charges) != 1 or len(real_charges) != 1 \
                    or len(env.new_requests(req1, "real")) != 1 or g_c.get("status") != "done" \
                    or (g_c.get("finalReal") or {}).get("status") != "done" or res_after is not None or len(starts) != 1 \
                    or env.ledger[led2:] or env.requests[req2:] or env.gen(pid_b)["realRun"]["n"] != 1:
                bad.append(f"(tb-c) 웹툰 완료 순회의 자동 시작 1번·원장 1번·다음 순회 0번이 아닙니다: {hit} "
                           f"웹툰 원장 {len(web_charges)} 실사 원장 {len(real_charges)} {g_c.get('status')} {res_after} {len(starts)}")
            if not logs.messages("vnew.gen.auto_real_start pid=prj_tb_b n=1"):
                bad.append("(tb-c) 자동 시작 로그가 없습니다")
            seen.add("tb-c")

            # ================= (tb-d) 웹툰 실패·취소·자동 시작 거절 =================
            pid_d = "prj_tb_d"
            _, total_d = fresh(pid_d)
            env.reject.add("webtoon")
            post(pid_d, {"confirmUsd": total_d, "styles": both})
            g_d = env.drive(pid_d)
            auto_d = dict(g_d.get("autoReal") or {})
            genmod.retry_segment(owner, pid_d, g_d["units"][0]["id"], "webtoon")
            auto_retry = dict(env.gen(pid_d).get("autoReal") or {})
            g_d2 = env.drive(pid_d)
            pid_x = "prj_tb_x"
            _, total_x = fresh(pid_x)
            post(pid_x, {"confirmUsd": total_x, "styles": both})
            genmod.cancel_gen(owner, pid_x)
            g_x = env.drive(pid_x)
            # 작업 163: 실패한 웹툰 칸을 다시 시도하면 autoReal.error 를 지우고, 웹툰이 done 이 되면 실사를 1번 자동 시작한다 —
            # 전에는 g_d2 에 realRun 이 없어야 했고 starts 가 1 이었다(이제 realRun n=1·startedAt·starts 2).
            if g_d.get("status") != "partial" or auto_d.get("error") != genmod.AUTO_REAL_SKIP_TEXT or auto_d.get("startedAt") \
                    or "error" in auto_retry or auto_retry.get("startedAt") \
                    or g_d2.get("status") != "done" or (g_d2.get("realRun") or {}).get("n") != 1 \
                    or not (g_d2.get("autoReal") or {}).get("startedAt") or (g_d2.get("autoReal") or {}).get("error") \
                    or g_x.get("status") != "cancelled" \
                    or (g_x.get("autoReal") or {}).get("error") != genmod.AUTO_REAL_CANCEL_TEXT or g_x.get("realRun") or len(starts) != 2:
                bad.append(f"(tb-d) 웹툰 실패·다시 시도·취소의 실사 자동 시작·autoReal.error 가 다릅니다: {g_d.get('status')} {auto_d} "
                           f"{auto_retry} {g_d2.get('status')} {g_d2.get('autoReal')} {g_x.get('status')} {g_x.get('autoReal')} "
                           f"{len(starts)}")
            pid_f = "prj_tb_f"
            _, total_f = fresh(pid_f)
            post(pid_f, {"confirmUsd": total_f, "styles": both})
            fail_start.append("실사 사진이 없는 등장인물이 있습니다: 비")
            g_f = env.drive(pid_f)
            view_f = genmod.gen_view(owner, pid_f, env.plan(pid_f))
            # 작업 163: prj_tb_d 다시 시도 뒤 자동 시작이 1번 늘어 starts 2 → 3.
            if g_f.get("status") != "done" or g_f.get("realRun") or len(starts) != 3 \
                    or (g_f.get("autoReal") or {}).get("error") != "실사 사진이 없는 등장인물이 있습니다: 비" \
                    or not (g_f.get("autoReal") or {}).get("startedAt") or view_f.get("canStartReal") is not True \
                    or not logs.messages("vnew.gen.auto_real_failed pid=prj_tb_f kind=CharacterRealMissing", logging.WARNING):
                bad.append(f"(tb-d) 자동 시작 거절이 autoReal.error·버튼(canStartReal)으로 남지 않았습니다: {g_f.get('autoReal')}")
            seen.add("tb-d")

            # ================= (tb-e) 끔·컷 단위 400, 변형 =================
            pid_e = "prj_tb_e"
            _, total_e = fresh(pid_e)
            with _pin_vnew(VNEW_TAKE_REAL=False):
                off_e = post(pid_e, {"confirmUsd": total_e, "styles": both})
            pid_k = "prj_tb_k"
            env.make_plan(pid_k, seg)
            env.planmod.mutate_plan(owner, pid_k, lambda data: data["input"].update(videoModel=""))
            cut_k = post(pid_k, {"confirmUsd": total_e, "styles": both})
            if off_e != (400, "TakeRealDisabled") or cut_k != (400, "RealNotTake") or env.gen(pid_e) or env.gen(pid_k):
                bad.append(f"(tb-e) 끔·컷 단위의 \"real\" 이 400 이 아닙니다: {off_e} {cut_k}")
            saved_wants = genmod._wants_real  # noqa: SLF001
            genmod._wants_real = lambda styles: False  # noqa: SLF001 — 변형: styles 를 무시
            try:
                mutant = post(pid_k, {"confirmUsd": total_e, "styles": both})
            finally:
                genmod._wants_real = saved_wants  # noqa: SLF001
            if mutant[0] == 400:
                bad.append(f"(tb-e) 변형(styles 무시)을 컷 단위 400 검사가 잡지 못합니다: {mutant}")
            seen.add("tb-e")
            if real_calls or env.urlopen_calls:
                bad.append(f"가짜가 아닌 호출이 있었습니다: {real_calls} {env.urlopen_calls}")
    except Exception as exc:  # noqa: BLE001
        bad.append("작업 123 서버 검사 중 예외: " + repr(exc) + "\n" + _tb.format_exc()[:2000])

    # ================= (tb-f) 화면 =================
    vjs = (PUBLIC / "vnew.js").read_text(encoding="utf-8")
    css = (PUBLIC / "vnew.css").read_text(encoding="utf-8")
    for needle in ('var GEN_WEBTOON_TITLE = "애니(웹툰)";', '["④", "영상(실사·애니(웹툰))"],',
                   '{ key: "webtoon", title: "애니(웹툰)" }; // 작업 123', 'webtoon: "애니(웹툰)" }; // 작업 123',
                   "EDIT_VARIANT_LABEL[item.key]);"):
        if vjs.count(needle) != 1:
            bad.append(f"(tb-f) vnew.js 에 \"애니(웹툰)\" 이름 배선이 없거나 두 번 있습니다: {needle}")
    for cls in (".vnew-gen-styles", ".vnew-gen-style", ".vnew-real-auto"):
        if not re.search(r"^" + re.escape(cls) + r" \{", css, re.M):
            bad.append(f"(tb-f) vnew.css 에 {cls} 가 없습니다")
    node = shutil.which("node")
    if not node:
        warn("node 가 없어 작업 123 화면 검사를 건너뜁니다")
    else:
        checked = subprocess.run([node, "--check", str(PUBLIC / "vnew.js")], capture_output=True, text=True, encoding="utf-8")
        if checked.returncode != 0:
            bad.append(f"(tb-f) node --check vnew.js 실패: {(checked.stderr or '').strip()[:300]}")
        code, problems = _lr_screen_code(vjs)
        hint_code, _poll_code, problems2 = _lr_095_code(vjs)
        bad.extend(problems + problems2)
        if not problems and not problems2:
            got, err = _lr_run_node(node, _LR_SCREEN_NODE_HARNESS + code + hint_code + _LR_095_HINT_STUBS + _TB123_NODE_CASES, "tb123_")
            path = "/api/vnew/p/p%201/generate"
            web = ["애니(웹툰)", "vnew-gen-style", "애니(웹툰)는 항상 만듭니다."]
            want = {
                "both": [[["checkbox", True, True], ["checkbox", True, False]], [web, ["실사", "vnew-gen-style", ""]],
                         "애니 $3.08 + 실사 $3.08 = $6.16"],
                "bothBody": ["POST", path, {"confirmUsd": 6.16, "styles": both}],
                "webOnly": ["애니 $3.08", ["POST", path, {"confirmUsd": 3.08, "styles": ["webtoon"]}]],
                "blocked": [[["checkbox", True, True], ["checkbox", False, True]],
                            [web, ["실사", "vnew-gen-style is-off", "실사 버전 기능이 꺼져 있습니다."]], "애니 $3.08",
                            ["POST", path, {"confirmUsd": 3.08, "styles": ["webtoon"]}]],
                "cut": [0, "예상 비용이 듭니다.", ["POST", path, {"confirmUsd": 4}]],
                "pending": [[["vnew-hint vnew-real-auto", "애니가 끝나면 실사를 자동으로 시작합니다"]], []],
                "failed": [[["vnew-hint vnew-real-lead", "같은 프리비즈 녹화로 실사 버전을 만들 수 있습니다. 웹툰 결과는 그대로 남습니다."]],
                           [["primary-button vnew-real-start", "실사 버전 만들기 ($3.08)", False]]],
                "heads": ["실사", "애니(웹툰)"],
                "sound": "소리: 애니(웹툰)",
            }
            if err:
                bad.append(f"(tb-f) node 실행 실패: {err}")
            else:
                for key, value in want.items():
                    if got.get(key) != value:
                        bad.append(f"(tb-f) 화면 {key} 가 다릅니다: {got.get(key)} != {value}")
    seen.add("tb-f")

    missing = [f"tb-{c}" for c in "abcdef" if f"tb-{c}" not in seen]
    if missing and not bad:
        bad.append(f"끝까지 돌지 않은 검사: {missing}")
    if bad:
        fail("작업 123 실사·애니(웹툰) 함께 만들기 검사 실패\n" + "\n".join(f"  {item}" for item in bad))
    else:
        ok("작업 123 실사·애니(웹툰) 함께 만들기 (tb-a)styles 생략 그대로 (tb-b)합계 409·모양 400·autoReal "
           "(tb-c)웹툰 완료 순회 자동 시작 1번·원장 1번·다음 0번 (tb-d)실패·취소·거절 (tb-e)끔·컷 400·변형 잡음 "
           "(tb-f)확인창 체크 2개·합계·애니(웹툰) 이름")


def check_seedream_fal_124() -> None:
    """작업 124 — Seedream 그림을 fal 로(기본 VPOC_SEEDREAM_PROVIDER=fal) · ark 그대로 · ark 인증 실패면 그 호출만 fal. 유료·네트워크 0.

    (sf-a) fal t2i 바디 {prompt, image_size, num_images, sync_mode}·이미지 0·model 무시, 결과 JPEG 요청 크기(1920x1080)
    (sf-b) fal edit 바디 image_urls = _data_url 순서대로·10장 상한
    (sf-c) fal_image_size 범위 안·작음(늘림)·큼(줄임)·꼴 틀림, 변형 1회(크기 변환 없음)를 (sf-a) 판정이 잡음
    (sf-d) 결과가 https URL 이면 _fetch_url 1번 → JPEG
    (sf-e) fal 422 content checker → generate_safe 다시 쓰기 단계(같은 문장 2번 → 다시 쓴 문장), 필터 아닌 422 는 바로 올림
    (sf-f) ark 401 "API key doesn't exist" → fal 1회·경고 1줄·로그에 키 없음, 404+같은 문구도 전환, ark 500 은 전환 없음
    (sf-g) ark 정상 → 작업 124 전과 같은 바디 bytes·주소·헤더, fal 0회
    (sf-h) 금액 unit_usd: fal 0.04(VPOC_SEEDREAM_FAL_USD) · ark VPOC_SEEDREAM_USD, ledger.charge_seedream 이 그 값을 쓴다
    """
    sys.path.insert(0, str(ROOT / "app"))
    import base64 as _b64  # noqa: PLC0415
    import io as _io  # noqa: PLC0415
    import traceback as _tb  # noqa: PLC0415
    import urllib.error as _uerr  # noqa: PLC0415
    import urllib.request as _ureq  # noqa: PLC0415

    from PIL import Image as _Image  # noqa: PLC0415

    from src.vpoc import fal as vpoc_fal  # noqa: PLC0415
    from src.vpoc import ledger as vpoc_ledger  # noqa: PLC0415
    from src.vpoc import llm as vpoc_llm  # noqa: PLC0415
    from src.vpoc import seedream as sd  # noqa: PLC0415
    from src.vpoc import settings as vs  # noqa: PLC0415
    from src.vpoc.errors import VpocError  # noqa: PLC0415

    bad: list[str] = []
    seen: set[str] = set()
    t2i = "fal-ai/bytedance/seedream/v4.5/text-to-image"
    edit = "fal-ai/bytedance/seedream/v4.5/edit"
    ark_model = "dola-seedream-5-0-pro-260628"
    ark_key = "ark-secret-KEY-124"

    def png(width: int, height: int, color=(10, 20, 30)) -> bytes:
        buffer = _io.BytesIO()
        _Image.new("RGB", (width, height), color).save(buffer, format="PNG")
        return buffer.getvalue()

    def small_jpeg(index: int) -> bytes:
        buffer = _io.BytesIO()
        _Image.new("RGB", (64, 48), (index * 20 % 256, 40, 200 - index * 10)).save(buffer, format="JPEG")
        return buffer.getvalue()

    def jpeg_size(raw: bytes):
        if not isinstance(raw, bytes) or raw[:2] != b"\xff\xd8":
            return None
        with _Image.open(_io.BytesIO(raw)) as image:
            return image.format, image.size

    calls: list[tuple] = []
    state = {"out": (2560, 1440), "reject": 0, "reject_msg": "", "https": False}

    def fake_request(method, url, payload=None, *, where):
        calls.append((method, url, payload, where))
        if method == "POST":
            return {"request_id": f"req{len(calls)}"}
        if url.endswith("/status"):
            return {"status": "COMPLETED"}
        if state["reject"] > 0:
            state["reject"] -= 1
            raise VpocError(where, "HTTP422", state["reject_msg"], 502)
        if state["https"]:
            return {"images": [{"url": "https://v3.fal.media/files/x/out.png"}]}
        return {"images": [{"url": "data:image/png;base64," + _b64.b64encode(png(*state["out"])).decode("ascii")}]}

    net: list = []

    def blocked_urlopen(*args, **kwargs):
        net.append(args)
        raise RuntimeError("network blocked in check")

    def posts() -> list[tuple]:
        return [c for c in calls if c[0] == "POST"]

    def t2i_ok(post: tuple, prompt: str) -> bool:
        return post[1] == f"{vs.FAL_QUEUE_URL}/{t2i}" and post[2] == {
            "prompt": prompt, "image_size": {"width": 2560, "height": 1440}, "num_images": 1, "sync_mode": True}

    names = ("SEEDREAM_PROVIDER", "FAL_KEY", "ARK_API_KEY", "SEEDREAM_USD", "SEEDREAM_FAL_USD",
             "SEEDREAM_FAL_EDIT_MODEL", "SEEDREAM_FAL_T2I_MODEL")
    saved_settings = {name: getattr(vs, name) for name in names}
    saved = {"request": vpoc_fal._request, "urlopen": _ureq.urlopen, "sleep": sd._sleep,  # noqa: SLF001
             "size": sd.fal_image_size, "fetch": sd._fetch_url, "rewrite": vpoc_llm.safe_image_prompt,  # noqa: SLF001
             "charge": vpoc_ledger.charge}
    logs = _LogCapture()
    try:
        with logs:
            if "VPOC_SEEDREAM_PROVIDER" not in os.environ and saved_settings["SEEDREAM_PROVIDER"] != "fal":
                bad.append(f"기본 공급자가 fal 이 아닙니다: {saved_settings['SEEDREAM_PROVIDER']}")
            vs.SEEDREAM_PROVIDER, vs.FAL_KEY, vs.ARK_API_KEY = "fal", "dummy-fal-key", ark_key
            vs.SEEDREAM_FAL_EDIT_MODEL, vs.SEEDREAM_FAL_T2I_MODEL = edit, t2i
            vpoc_fal._request = fake_request  # noqa: SLF001
            _ureq.urlopen = blocked_urlopen
            sd._sleep = lambda _s: None  # noqa: SLF001

            # ================= (sf-a) t2i =================
            out_a = sd.generate("a quiet room", None, model=ark_model, where="t.a", size="1920x1080")
            gets_a = [c[1] for c in calls if c[0] == "GET"]
            if len(posts()) != 1 or not t2i_ok(posts()[0], "a quiet room") or "image_urls" in posts()[0][2] \
                    or jpeg_size(out_a) != ("JPEG", (1920, 1080)) \
                    or gets_a != [vpoc_fal._status_url(t2i, "req1"), vpoc_fal._response_url(t2i, "req1")]:  # noqa: SLF001
                bad.append(f"(sf-a) t2i 바디·결과가 다릅니다: {[(c[1], c[2]) for c in posts()]} {jpeg_size(out_a)} {gets_a}")
            seen.add("sf-a")

            # ================= (sf-b) edit =================
            calls.clear()
            refs = [small_jpeg(i) for i in range(12)]
            out_b = sd.generate("Image 1 is the room.", refs, model=ark_model, where="t.b", size="2560x1440")
            post_b = posts()[0] if posts() else ("", "", {})
            want_urls = [sd._data_url(item) for item in refs[:10]]  # noqa: SLF001
            if len(posts()) != 1 or post_b[1] != f"{vs.FAL_QUEUE_URL}/{edit}" \
                    or (post_b[2] or {}).get("image_urls") != want_urls \
                    or (post_b[2] or {}).get("image_size") != {"width": 2560, "height": 1440} \
                    or "model" in (post_b[2] or {}) or jpeg_size(out_b) != ("JPEG", (2560, 1440)):
                bad.append(f"(sf-b) edit 바디가 다릅니다: url={post_b[1]} n={len((post_b[2] or {}).get('image_urls') or [])} "
                           f"{jpeg_size(out_b)}")
            seen.add("sf-b")

            # ================= (sf-c) 크기 순수 함수 + 변형 =================
            sizes = [sd.fal_image_size(x) for x in ("2560x1440", "1440x2560", "1920x1080", "8192x4608", "bad")]
            if sizes != [(2560, 1440), (1440, 2560), (2560, 1440), (4096, 2304), (2560, 1440)]:
                bad.append(f"(sf-c) fal_image_size 가 다릅니다: {sizes}")
            calls.clear()
            sd.fal_image_size = lambda size: sd._parse_wh(size)  # noqa: SLF001 — 변형: 범위 맞추기 없음
            sd.generate("a quiet room", None, model=ark_model, where="t.c", size="1920x1080")
            if not posts() or t2i_ok(posts()[0], "a quiet room"):
                bad.append("(sf-c) 변형(크기 변환 없음)을 (sf-a) 판정이 잡지 못했습니다")
            sd.fal_image_size = saved["size"]
            seen.add("sf-c")

            # ================= (sf-d) https 결과 =================
            calls.clear()
            fetched: list[str] = []

            def fake_fetch(url, where):
                fetched.append(url)
                return png(2560, 1440)

            sd._fetch_url = fake_fetch  # noqa: SLF001
            state["https"] = True
            out_d = sd.generate("x", None, model=ark_model, where="t.d", size="1920x1080")
            state["https"] = False
            sd._fetch_url = saved["fetch"]  # noqa: SLF001
            if fetched != ["https://v3.fal.media/files/x/out.png"] or jpeg_size(out_d) != ("JPEG", (1920, 1080)) or net:
                bad.append(f"(sf-d) https 결과 받기가 다릅니다: {fetched} {jpeg_size(out_d)} net={len(net)}")
            seen.add("sf-d")

            # ================= (sf-e) 안전 필터 → 다시 쓰기 =================
            calls.clear()
            rewrites: list[str] = []

            def fake_rewrite(prompt):
                rewrites.append(prompt)
                return "calm rewritten scene", {}

            vpoc_llm.safe_image_prompt = fake_rewrite
            state["reject"], state["reject_msg"] = 2, (
                "The content could not be processed because it contained material flagged by a content checker.")
            out_e = sd.generate_safe("Style. Scene: a fight", None, model=ark_model, where="t.e")
            prompts_e = [c[2]["prompt"] for c in posts()]
            if prompts_e != ["Style. Scene: a fight"] * 2 + ["calm rewritten scene"] or rewrites != ["Style. Scene: a fight"] \
                    or jpeg_size(out_e) != ("JPEG", (1920, 1080)) or len(logs.messages("vpoc.seedream.filtered")) != 2:
                bad.append(f"(sf-e) 필터 다시 쓰기가 돌지 않았습니다: {prompts_e} {rewrites}")
            calls.clear()
            rewrites.clear()
            state["reject"], state["reject_msg"] = 1, "image_size: width must be an integer"
            try:
                sd.generate_safe("p", None, model=ark_model, where="t.e2")
                bad.append("(sf-e) 필터 아닌 422 가 올라오지 않았습니다")
            except VpocError as exc:
                if exc.kind != "HTTP422" or len(posts()) != 1 or rewrites:
                    bad.append(f"(sf-e) 필터 아닌 422 처리 다름: {exc.kind} posts={len(posts())}")
            state["reject"] = 0
            seen.add("sf-e")

            # ================= (sf-f) ark 인증 실패 → fal 1회 =================
            vs.SEEDREAM_PROVIDER = "ark"
            ark_seen: list = []

            def ark_error(code: int, message: str):
                def opener(request, timeout=None):
                    ark_seen.append(request)
                    body = json.dumps({"error": {"code": "AuthenticationError", "message": message}}).encode()
                    raise _uerr.HTTPError(request.full_url, code, "err", {}, _io.BytesIO(body))
                return opener

            for code, msg, want_fal in ((401, "The API key doesn't exist. Request id: 0217", 1),
                                        (404, "The API key doesn't exist. Request id: 0218", 1),
                                        (500, "Internal error", 0)):
                calls.clear()
                ark_seen.clear()
                logs.clear()
                _ureq.urlopen = ark_error(code, msg)
                try:
                    out_f = sd.generate("p", None, model=ark_model, where="t.f", size="1920x1080")
                    got = ("ok", jpeg_size(out_f))
                except VpocError as exc:
                    got = ("err", exc.kind)
                warns = logs.messages("vpoc.seedream.ark_auth_fallback")
                every = logs.messages("")
                if len(ark_seen) != 1 or len(posts()) != want_fal or any(ark_key in m for m in every):
                    bad.append(f"(sf-f) ark {code} 전환이 다릅니다: ark={len(ark_seen)} fal={len(posts())} {got}")
                elif want_fal and (got != ("ok", ("JPEG", (1920, 1080))) or len(warns) != 1 or "kind=HTTP" not in warns[0]):
                    bad.append(f"(sf-f) ark {code} 전환 결과·경고가 다릅니다: {got} {warns}")
                elif not want_fal and (got != ("err", "HTTP500") or warns):
                    bad.append(f"(sf-f) ark 500 이 전환됐습니다: {got} {warns}")
            seen.add("sf-f")

            # ================= (sf-g) ark 정상 → 같은 바디 =================
            calls.clear()
            captured: list = []

            class _Resp:
                def __init__(self, raw: bytes) -> None:
                    self._raw = raw

                def read(self, *_a):
                    return self._raw

                def __enter__(self):
                    return self

                def __exit__(self, *_a):
                    return False

            def ark_ok(request, timeout=None):
                captured.append((request, timeout))
                b64 = _b64.b64encode(png(1920, 1080)).decode("ascii")
                return _Resp(json.dumps({"data": [{"b64_json": b64}]}).encode())

            _ureq.urlopen = ark_ok
            refs_g = refs[:11]
            out_g = sd.generate("ark prompt", refs_g, model=ark_model, where="t.g", size="2560x1440")
            want_body = json.dumps({
                "model": ark_model, "prompt": "ark prompt", "size": "2560x1440", "response_format": "b64_json",
                "watermark": False, "image": [sd._data_url(item) for item in refs_g[:10]],  # noqa: SLF001
            }).encode("utf-8")
            req_g = captured[0][0] if captured else None
            if req_g is None or req_g.data != want_body or req_g.full_url != vs.ARK_BASE_URL + "/images/generations" \
                    or req_g.get_header("Authorization") != "Bearer " + ark_key or captured[0][1] != 300 \
                    or req_g.get_method() != "POST" or calls or jpeg_size(out_g) != ("JPEG", (1920, 1080)):
                bad.append(f"(sf-g) ark 바디가 작업 124 전과 다릅니다: fal={len(calls)} {jpeg_size(out_g)}")
            seen.add("sf-g")

            # ================= (sf-h) 금액 =================
            charged: list[float] = []
            vpoc_ledger.charge = lambda key, **kw: charged.append(kw["usd"]) or {}
            vs.SEEDREAM_USD, vs.SEEDREAM_FAL_USD = 0.035, 0.04
            vs.SEEDREAM_PROVIDER = "fal"
            usd_fal = sd.unit_usd()
            vpoc_ledger.charge_seedream("k1", model=ark_model, user="u", project_id="p", plan_id="x")
            vs.SEEDREAM_PROVIDER = "ark"
            usd_ark = sd.unit_usd()
            vpoc_ledger.charge_seedream("k2", model=ark_model, user="u", project_id="p", plan_id="x")
            if (usd_fal, usd_ark) != (0.04, 0.035) or charged != [0.04, 0.035] or saved_settings["SEEDREAM_FAL_USD"] != 0.04 \
                    and "VPOC_SEEDREAM_FAL_USD" not in os.environ:
                bad.append(f"(sf-h) 금액이 다릅니다: fal={usd_fal} ark={usd_ark} ledger={charged}")
            seen.add("sf-h")
            if net:
                bad.append(f"네트워크 호출이 있었습니다: {len(net)}")
    except Exception:  # noqa: BLE001
        bad.append("작업 124 검사 예외\n" + _tb.format_exc())
    finally:
        for name, value in saved_settings.items():
            setattr(vs, name, value)
        vpoc_fal._request = saved["request"]  # noqa: SLF001
        _ureq.urlopen = saved["urlopen"]
        sd._sleep = saved["sleep"]  # noqa: SLF001
        sd.fal_image_size = saved["size"]
        sd._fetch_url = saved["fetch"]  # noqa: SLF001
        vpoc_llm.safe_image_prompt = saved["rewrite"]
        vpoc_ledger.charge = saved["charge"]
    missing = {"sf-a", "sf-b", "sf-c", "sf-d", "sf-e", "sf-f", "sf-g", "sf-h"} - seen
    if missing:
        bad.append(f"돌지 않은 검사: {sorted(missing)}")
    if bad:
        fail("작업 124 Seedream fal\n" + "\n".join(f"  {item}" for item in bad))
    else:
        ok("작업 124 Seedream fal (sf-a)t2i 바디 (sf-b)edit image_urls 10장 (sf-c)크기 3경우·변형 잡힘 (sf-d)https 결과 "
           "(sf-e)필터 다시 쓰기 (sf-f)ark 인증 실패 fal 1회·키 없음 (sf-g)ark 바디 그대로 (sf-h)금액 unit_usd")


def _snd_mp4(ffmpeg: str, path: str, *, audio: bool) -> None:
    """작업 122 검사용 합성 mp4(4초, 160x120 색 영상 24fps). audio 면 440Hz 사인파를 0.5~1.5초·2.5~3.5초에만 낸다(나머지 무음)."""
    command = [ffmpeg, "-y", "-hide_banner", "-loglevel", "error", "-f", "lavfi", "-i", "color=c=blue:s=160x120:r=24:d=4"]
    if audio:
        command += ["-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000:duration=4",
                    "-af", "volume=enable='between(t,0,0.5)+between(t,1.5,2.5)+between(t,3.5,4)':volume=0",
                    "-c:a", "aac", "-b:a", "128k", "-shortest"]
    command += ["-c:v", "libx264", "-pix_fmt", "yuv420p", path]
    result = subprocess.run(command, capture_output=True)
    if result.returncode != 0:
        raise RuntimeError("합성 mp4 를 만들지 못했습니다: " + result.stderr.decode("utf-8", errors="replace")[-300:])


def _snd_video_md5(ffmpeg: str, path: str) -> str:
    result = subprocess.run([ffmpeg, "-hide_banner", "-loglevel", "error", "-i", path, "-map", "0:v:0", "-c", "copy", "-f", "md5", "-"],
                            capture_output=True)
    return result.stdout.decode("utf-8", errors="replace").strip()


def _snd_pcm(ffmpeg: str, path: str) -> bytes:
    """소리 디코드(s16le 모노 48kHz)."""
    return subprocess.run([ffmpeg, "-hide_banner", "-loglevel", "error", "-i", path, "-map", "0:a:0", "-f", "s16le", "-ac", "1",
                           "-ar", "48000", "-"], capture_output=True).stdout


