def _tc157_plan() -> tuple[dict, dict]:
    """작업 157 손 추출 계획(23초 테이크 1개, 녹화 1구간). 프리비즈 hands: cut-06 범건우 오른손 cup 상대 목."""
    a, b = _TC157_A, _TC157_B
    cuts, timeline, briefs, grammar = [], [], {}, {}
    for no, (cid, seconds, panels, dialogue, chars, action, (main, others), fx) in enumerate(_TC157_CUTS, start=1):
        cut = {"id": cid, "no": no, "seconds": seconds, "panels": panels, "dialogueKo": dialogue,
               "locationEn": "Outdoors by a low metal railing", "characters": [{"name": n, "actionEn": t} for n, t in chars]}
        if fx:
            cut.update(fx=list(fx), fxWho={fx[0]: [b]})
        cuts.append(cut)
        lead = {"id": "a1"}
        if cid == "cut-06":
            lead = {"id": "a1", "gestureTarget": "a2",
                    "hands": {"right": {"act": "cup", "target": "other_neck"}, "left": {"act": "rest", "target": "none"}}}
        timeline.append({"cutId": cid, "actors": [lead, {"id": "a2"}]})
        briefs[cid] = {"shotEn": "MCU, 50 mm, eye-level three-quarter.", "actionEn": action}
        grammar[cid] = {"grammar": {"mainSubject": main, "shotSize": "MCU", "shotType": "single", "vantage": "front",
                                    "others": [{"name": n, "how": "hands_only" if cid == "cut-06" else "full"} for n in others]}}
    ids = [c["id"] for c in cuts]
    plan = {
        "conti": {"status": "ready", "cuts": cuts, "segments": [{"id": "s1", "cutIds": ids, "seconds": 23}]},
        "script": {"status": "ready", "setting": {"timeKo": "낮", "locationEn": "Outdoors by a low metal railing"},
                   "entries": [{"id": i, "panels": p, "speaker": s, "lineKo": t, "voice": "thought" if th else "spoken"}
                               for i, p, s, t, th in _TC157_SCRIPT]},
        "locations": [{"key": "outdoors by a low metal railing", "nameEn": "Outdoors by a low metal railing",
                       "design": {"lightEn": "Cool-white store light from the glass front, blue-grey evening fill."}}],
        "previz": {"status": "ready", "recordings": {"s1": {"key": "PREVIZ-REC-s1", "seconds": 23}},
                   "scenes": [{"locationId": "loc1", "timeline": timeline,
                               "actors": [{"id": "a1", "name": a, "color": "#f58231"}, {"id": "a2", "name": b, "color": "#4363d8"}]}],
                   "panelGrammar": grammar, "shotBrief": {"status": "ready", "cuts": briefs}},
    }
    take = {"id": "take1", "cutIds": ids, "recKeys": ["PREVIZ-REC-s1"], "recSegIds": ["s1"], "seconds": 23.0}
    return plan, take


def check_vnew_take_conti_157() -> None:
    """작업 157 — 테이크 프롬프트가 콘티 전체(모든 컷 연기·모든 대사)를 싣고 고정 문구를 먼저 줄인다. 가짜, 유료 0.

    (tc-a) 한 줄 한 컷: test3 손 추출 cut-01~06 의 _cut_lines = 콘티 dialogueKo(패널 1 의 e3 는 cut-01 만), 패널이 겹치는 두 컷에서
           콘티에 대사가 든 컷(test3 cut-12 [19,20]·cut-13 [20] → cut-13), 나눈 컷 같은 대사(147 still)는 그대로
    (tc-b) 실제 예산(4,000자)·조각 c01–c02·c03–c06·애니·실사: 모든 대사 정확히 1번·제 컷 안, 모든 컷 연기(통문장, 낱말 가운데서 끊김 없음),
           cut-04/05/06 닿는 연기, 실사 cut-02 "음… 이제 더 할 말도 없어요. 곧 괜찮아지겠죠.", 실사·애니 같은 대사·닿는 연기, audit 줄 수 같음
    (tc-c) 아주 작은 예산: 고정 부분이 모두 짧은 형이 된 뒤에만 컷 내용을 줄이고 대사 줄 수 그대로, 그래도 넘치면 컷 경계 조각으로
           더 나눈다(_prompt_split_parts: 조각마다 상한 안 또는 컷 1개, 컷·시각 이어짐, 대사 줄 합 그대로)
    (tc-d) 제출: 넘치는 통 테이크(가짜 fal Seedance) → 조각 여러 개로 제출, 조각 프롬프트에 자기 컷 대사만·모두 합치면 전부,
           제출마다 vnew.gen.prompt_audit 1줄 lines_in_conti = lines_in_prompt
    (tc-e) 예산 단위 = 글자(VNEW_TAKE_PROMPT_MAX_CHARS 4000, 스키마 maxLength 는 글자), _action_core 는 낱말 가운데서 자르지 않는다
    """
    import traceback as _tb  # noqa: PLC0415

    sys.path.insert(0, str(ROOT / "app"))
    from src.vnew import fx as fxmod  # noqa: PLC0415
    from src.vnew import generate as genmod  # noqa: PLC0415

    bad: list[str] = []
    report: list[str] = []

    def expect(group: str, got, want, what: str) -> None:
        if got != want:
            bad.append(f"({group}) {what}\n      결과 {got!r}\n      기대 {want!r}")

    anime_cast = [{"name": _TC157_B, "colorName": "blue", "frontNo": 1, "appearance": "", "voice": "",
                   "costume": "Black long-sleeve track top with a single white stripe down each sleeve"},
                  {"name": _TC157_A, "colorName": "orange", "frontNo": 2, "appearance": "", "voice": "",
                   "costume": "Dark navy long-sleeve button-up dress shirt, collar open, worn untucked"}]
    real_cast = [dict(anime_cast[0], frontNo=2, sheetNo=1, refNos=[1, 2], look="real",
                      appearance="a Korean man in his 20s with tousled pale blonde hair and long sweeping bangs"),
                 dict(anime_cast[1], frontNo=4, sheetNo=3, refNos=[3, 4], look="real",
                      appearance="narrow half-lidded eyes and short charcoal-black hair swept back")]
    source = " ".join(c[5] for c in _TC157_CUTS) + " " + " ".join(
        str(table) for table in (fxmod.FX_SENTENCE, fxmod.REAL_FX, fxmod.FX_WHO_SENTENCE, fxmod.REAL_WHO, fxmod.FX_WHO_NOT))

    def prompt(plan, take, variant: str, audit: dict | None = None, caps=None) -> str:
        cast, panels, loc = (real_cast, [], 5) if variant == "real" else (anime_cast, [3, 4, 5], 6)
        kw = {"variant": "real"} if variant == "real" else {}
        return genmod._take_prompt(plan, take, cast=cast, panel_nos=panels, location_no=loc, caps=caps,  # noqa: SLF001
                                   audit=audit, **kw)

    def segments(plan, take, text: str) -> dict[str, str]:
        tl = next((ln for ln in text.split("\n") if ln.startswith("TIMELINE")), "")
        entries = genmod._take_timeline_entries(plan, take)  # noqa: SLF001
        stamps = [f"{e['start']}-{e['end']}s " for e in entries]
        out = {}
        for k, cid in enumerate(take["cutIds"]):
            at = tl.find(stamps[k])
            end = tl.find(stamps[k + 1], at + 1) if k + 1 < len(stamps) else len(tl)
            out[cid] = tl[at:end] if at >= 0 else ""
        return out

    def whole_sentences(action: str) -> bool:
        # 연기 조각의 문장마다 끝 낱말 + 문장부호가 원문(지시서·기호 문장)에 그 모양으로 있다 = 낱말·절 가운데서 끊지 않았다.
        for sentence in genmod._split_sentences(action):  # noqa: SLF001
            words = re.findall(r"[A-Za-z][\w'-]*", sentence)
            if not sentence.endswith((".", "!", "?")) or not words \
                    or not re.search(re.escape(words[-1]) + r"[.,;!?'\"]", source):
                return False
        return True

    try:
        with _guard_real_llm(), _pin_vnew(VNEW_FX=True, VNEW_TAKE_PROMPT_MAX_CHARS=4000):
            plan, take = _tc157_plan()
            # ================= (tc-a) 한 줄 한 컷 =================
            got_a = {c["id"]: [ln["lineKo"] for ln in genmod._cut_lines(plan, c) if not ln.get("silent")]  # noqa: SLF001
                     for c in plan["conti"]["cuts"]}
            want_a = {c[0]: [x.replace("(속마음)", "").strip() for x in c[3].split("\n") if x.strip() and x.strip() != "……."]
                      for c in _TC157_CUTS}
            tie = {"conti": {"cuts": [{"id": "cut-12", "panels": [19, 20], "dialogueKo": "정말 그 놈을 잊을 수 있을지."},
                                      {"id": "cut-13", "panels": [20], "dialogueKo": "한 번 시험 해 보자고."}]},
                   "script": {"entries": [{"id": "e23", "panels": [19], "speaker": _TC157_A, "lineKo": "정말 그 놈을 잊을 수 있을지."},
                                          {"id": "e24", "panels": [20], "speaker": _TC157_A, "lineKo": "한 번 시험 해 보자고."}]}}
            got_tie = [[ln["lineKo"] for ln in genmod._cut_lines(tie, c)] for c in tie["conti"]["cuts"]]  # noqa: SLF001
            split = [dict(c) for c in _DR147_CUTS if c["id"] in ("cut07-1", "cut07-2")]
            runs = genmod._dialogue_runs(split, {"conti": {"cuts": split}, "script": {"entries": []}})  # noqa: SLF001
            expect("tc-a", [got_a, got_tie, [[ln["run"] for ln in r] for r in runs]],
                   [want_a, [["정말 그 놈을 잊을 수 있을지."], ["한 번 시험 해 보자고."]], [["start"], ["still"]]],
                   "한 줄 한 컷(콘티 dialogueKo 와 같다)·패널 겹침은 콘티에 대사가 든 컷·나눈 컷 같은 대사는 147 그대로")

            # ================= (tc-b) 실제 예산·조각 c01–c02·c03–c06 =================
            parts = [{"cutIds": ["cut-01", "cut-02"], "seconds": 8.0},
                     {"cutIds": ["cut-03", "cut-04", "cut-05", "cut-06"], "seconds": 15.0}]
            found: dict[str, dict] = {"webtoon": {}, "real": {}}
            for variant in ("webtoon", "real"):
                for part in parts:
                    sub = genmod._part_take(plan, take, part)  # noqa: SLF001
                    audit: dict = {}
                    text = prompt(plan, sub, variant, audit)
                    segs = segments(plan, sub, text)
                    tl = next((ln for ln in text.split("\n") if ln.startswith("TIMELINE")), "")
                    for cid in sub["cutIds"]:
                        quotes = [f'"{q}"' for q in _TC157_QUOTES[cid]]
                        found[variant][cid] = {
                            "quotes": [(tl.count(q), q in segs[cid]) for q in quotes],
                            "contact": cid not in _TC157_CONTACT or _TC157_CONTACT[cid] in segs[cid],
                        }
                    actions = audit.get("actions") or []
                    label = f"{variant} {sub['cutIds'][0]}–{sub['cutIds'][-1]}"
                    expect("tc-b", [audit.get("fits"), audit.get("linesInPrompt") == audit.get("linesInConti"),
                                    audit.get("actionsInPrompt"), len(actions), all(a and a in text for a in actions),
                                    all(whole_sentences(a) for a in actions), "through the off." in text],
                           [True, True, len(sub["cutIds"]), len(sub["cutIds"]), True, True, False],
                           f"{label}: 4,000자 안·대사 줄 수 같음·모든 컷 통문장 연기·낱말 가운데 끊김 없음 {actions}")
                    report.append(f"{label}: {genmod._prompt_len(text)}자 {genmod._utf8_len(text)}B compact="  # noqa: SLF001
                                  f"{','.join(audit.get('compact') or []) or 'none'} 대사 {audit.get('linesInPrompt')}/"
                                  f"{audit.get('linesInConti')} 연기 {audit.get('actionsInPrompt')}/{audit.get('cuts')}")
                    if variant == "real" and "cut-02" in sub["cutIds"]:
                        expect("tc-b", "음… 이제 더 할 말도 없어요. 곧 괜찮아지겠죠." in segs["cut-02"], True, "실사 cut-02 여의준 대사")
            for variant in ("webtoon", "real"):
                expect("tc-b", found[variant], {cid: {"quotes": [(1, True)] * len(_TC157_QUOTES[cid]), "contact": True}
                                                for cid in _TC157_QUOTES},
                       f"{variant}: 콘티 대사가 모두 정확히 1번·제 컷 안, cut-04/05/06 닿는 연기")
            expect("tc-b", found["real"] == found["webtoon"], True, "실사 TIMELINE 의 대사·닿는 연기 = 애니(실사만 빼는 것 없음)")

            # ================= (tc-c) 아주 작은 예산 =================
            sub2 = genmod._part_take(plan, take, parts[1])  # noqa: SLF001
            order_157 = [s + "Compact" for s in genmod.TAKE_COMPACT_ORDER] + ["gazeDrop", "moodDrop", "fxShort", "actionFirst",
                                                                              "overBudget"]
            for variant in ("webtoon", "real"):
                for cap in (2600, 1500):
                    audit = {}
                    with _LogCapture() as logs:
                        text = prompt(plan, sub2, variant, audit, caps={"promptMaxLength": cap})
                    steps = next((m.rsplit("steps=", 1)[-1] for m in logs.messages("vnew.gen.take_prompt ")), "").split(",")
                    content = [s for s in steps if s in ("gazeDrop", "moodDrop", "fxShort", "actionFirst")]
                    expect("tc-c", [[s for s in order_157 if s in steps] == steps,
                                    not content or len(audit.get("compact") or []) == len(genmod.TAKE_COMPACT_ORDER),
                                    audit.get("linesInPrompt"), audit.get("actionsInPrompt"),
                                    audit.get("fits") == (genmod._prompt_len(text) <= cap)],  # noqa: SLF001
                           [True, True, 6, 4, True], f"{variant} {cap}자({','.join(steps)}): 고정 부분 먼저·대사 6줄·연기 4컷")
            audit = {}
            built = {"audit": audit, "probe": None}
            whole = prompt(plan, take, "webtoon", audit, caps={"promptMaxLength": 1500})

            def probe(sub_take: dict) -> dict:
                out: dict = {}
                with _LogCapture():
                    prompt(plan, sub_take, "webtoon", out, caps={"promptMaxLength": 1500})
                return out

            built["probe"] = probe
            split_parts = genmod._prompt_split_parts(plan, take, [], built)  # noqa: SLF001
            probes = [probe(genmod._part_take(plan, take, p)) for p in split_parts]  # noqa: SLF001
            with _LogCapture():
                texts = [prompt(plan, genmod._part_take(plan, take, p), "webtoon", {}, caps={"promptMaxLength": 1500})  # noqa: SLF001
                         for p in split_parts]
            # 대본 줄마다 정확히 한 조각에(147 이어진 말이 조각 경계에서 갈리면 조각마다 제 몫만 — 줄 수는 달라도 빠짐·겹침 없음).
            spread = [sum(t in x for x in texts) for _i, _p, _s, t, _th in _TC157_SCRIPT if t and t != "……."]
            chain = all(abs(split_parts[i]["end"] - split_parts[i + 1]["start"]) < 1e-6 for i in range(len(split_parts) - 1))
            expect("tc-c", [audit.get("fits"), len(split_parts) >= 2, [c for p in split_parts for c in p["cutIds"]],
                            all(pr.get("fits") or len(p["cutIds"]) == 1 for p, pr in zip(split_parts, probes)), chain,
                            split_parts[0]["start"] if split_parts else None, split_parts[-1]["end"] if split_parts else None,
                            all(pr.get("linesInPrompt") == pr.get("linesInConti") for pr in probes), spread,
                            genmod._prompt_split_parts(plan, take, [], {"audit": {"fits": True}, "probe": probe})],  # noqa: SLF001
                   [False, True, take["cutIds"], True, True, 0.0, 23.0, True, [1] * len(spread), []],
                   f"1,500자 통 테이크({genmod._prompt_len(whole)}자) → 조각 {[p['cutIds'] for p in split_parts]}: 조각마다 상한 안 "  # noqa: SLF001
                   "또는 컷 1개·컷·시각 이어짐·조각마다 대사 줄 그대로·대본 줄마다 한 조각, 들어가면 나누지 않음")
            report.append(f"1,500자 통 테이크 {genmod._prompt_len(whole)}자 → 조각 {[p['cutIds'] for p in split_parts]}")  # noqa: SLF001

            # ================= (tc-e) 예산 단위·자르기 =================
            core = genmod._action_core(_TC157_CUTS[0][5], 70)  # noqa: SLF001
            expect("tc-e", [genmod._take_prompt_budget(None), genmod._take_prompt_budget({"promptMaxLength": 1800}),  # noqa: SLF001
                            genmod._prompt_len("가나다"), core],  # noqa: SLF001
                   [4000, 1800, 3, "Hold on his furrowed brow and narrowed near-black eyes through the off-screen apology."],
                   "예산 = 글자(기본 4,000, 스키마 maxLength 도 글자)·_action_core 는 절 경계가 없으면 첫 문장 통째")

        # ================= (tc-d) 제출: 넘치는 통 테이크 → 조각, 감사 로그 =================
        _tc157_submit(bad, report)
    except Exception:  # noqa: BLE001
        bad.append("작업 157 검사 예외\n" + _tb.format_exc())
    if bad:
        fail("작업 157 테이크 프롬프트 콘티 전체 검사 실패\n  " + "\n  ".join(bad))
    else:
        ok("작업 157 콘티 전체 (tc-a)한 줄 한 컷·콘티 대사 컷·147 still (tc-b)4,000자 c01–c02·c03–c06 애니·실사 대사 1번·제 컷·"
           "통문장 연기·닿는 연기·실사 cut-02 (tc-c)고정 부분 먼저·대사 그대로·넘치면 조각 (tc-d)제출 조각·감사 로그 줄 수 같음 "
           "(tc-e)글자 예산·자르기")
        for line in report:
            print(f"       157: {line}")


def _tc157_submit(bad: list[str], report: list[str]) -> None:
    """(tc-d) 가짜 fal(Seedance r2v)·_LrEnv: 12초 4컷 테이크가 상한에 안 들어 조각으로 나눠 제출되고, 제출마다 감사 로그 1줄."""
    sys.path.insert(0, str(ROOT / "app"))
    from src.vnew import generate as genmod  # noqa: PLC0415
    from src.vnew import plan as planmod  # noqa: PLC0415

    owner, pid = "tester", "prj_tc157"
    with _guard_real_llm(), _LrEnv(owner) as env, _pin_vnew(
            VNEW_FX=False, VNEW_GEN_PARALLEL=1, POLL_INTERVAL_S=0, VNEW_TAKE_RESOLUTION="480p", VNEW_TAKE_REF_SPLIT=True,
            VNEW_TAKE_AUDIO=True, VNEW_PART_CONTINUITY=True, VNEW_TEXT_CHECK=False) as vset, _LogCapture() as logs:
        env.set(genmod, "_cut_clip", lambda mp4, unit: {
            "bytes": b"CLIP:%.3f-%.3f:" % (float(unit["startSec"]), float(unit["endSec"])) + bytes(mp4)[:20],
            "origSeconds": round(float(unit["endSec"]) - float(unit["startSec"]), 3),
            "sentSeconds": round(float(unit["endSec"]) - float(unit["startSec"]), 3), "padded": False})
        env.set(genmod, "_mp4_seconds", lambda mp4: 0.0)
        env.set(genmod, "_conform_concat", lambda pieces, **_kw: b"PARTS:%d" % len(pieces))
        env.set(genmod, "_cut_first_frame", lambda mp4, start: b"FRAME:" + bytes(mp4)[:10])
        env.make_plan(pid, [{"id": "s1", "cutIds": ["c1", "c2", "c3", "c4"], "seconds": 12}])

        def mutator(data: dict) -> None:
            for cut in data["conti"]["cuts"]:
                cut["panels"] = [cut["no"]]
                text = f"대사{cut['no']}번 " + "오늘은 정말 할 말이 많아서 처음부터 끝까지 다 이야기해 줄게 잘 들어."
                cut["dialogueKo"] = f'에이: "{text}"'
                data["previz"]["shotBrief"]["cuts"][cut["id"]] = {
                    "shotEn": "MCU.", "actionEn": f"Kim leans forward in cut {cut['no']} and speaks slowly. He keeps his eyes on Bi.",
                    "dialogue": [{"speaker": "에이", "lineKo": text, "deliveryEn": "calm"}]}

        planmod.mutate_plan(owner, pid, mutator)
        plan = env.plan(pid)
        take = genmod._take_units(plan)[0]  # noqa: SLF001
        caps = dict(_LR_CAPS)
        saved_limit = vset.VNEW_TAKE_PROMPT_MAX_CHARS  # fix1: 아래에서 바꾼 상한을 finally 에서 되돌린다(뒤 검사로 새지 않게)
        try:
            vset.VNEW_TAKE_PROMPT_MAX_CHARS = 100  # 다 줄인 길이를 잰다(로그 없음 probe)
            built = genmod._take_payload(owner, pid, plan, take, caps)  # noqa: SLF001
            whole_min = int(built["probe"](take).get("chars") or 0)
            half_min = int(built["probe"](genmod._part_take(plan, take, {"cutIds": ["c1", "c2"], "seconds": 6.0})).get("chars") or 0)  # noqa: SLF001
            vset.VNEW_TAKE_PROMPT_MAX_CHARS = (whole_min + half_min) // 2  # 4컷은 안 들고 2컷은 든다
            logs.clear()
            since = len(env.requests)
            client = env.client()
            client.post(f"/api/vnew/p/{pid}/generate", json={"confirmUsd": genmod.estimate(env.plan(pid))["totalUsd"]})
            g = env.drive(pid)
            used_limit = vset.VNEW_TAKE_PROMPT_MAX_CHARS
        finally:
            vset.VNEW_TAKE_PROMPT_MAX_CHARS = saved_limit
        reqs = env.requests[since:]
        state = genmod._previz_cells(g)[0]["webtoon"]  # noqa: SLF001
        part_ids = [p.get("cutIds") for p in state.get("parts") or []]
        lines = [set(re.findall(r"대사(\d+)번", str(r["payload"].get("prompt") or ""))) for r in reqs]
        audits = logs.messages("vnew.gen.prompt_audit ")
        counts = [(re.search(r"lines_in_conti=(\d+)", m).group(1), re.search(r"lines_in_prompt=(\d+)", m).group(1)) for m in audits]
        want_lines = [{str(int(c[1:])) for c in ids} for ids in part_ids]
        if len(part_ids) < 2 or [c for ids in part_ids for c in ids] != ["c1", "c2", "c3", "c4"] or lines != want_lines \
                or len(audits) != len(reqs) or any(a != b for a, b in counts) or state.get("status") != "completed":
            bad.append(f"(tc-d) 넘치는 통 테이크 제출: 조각 {part_ids} 요청 대사 {lines} 감사 {counts} 상태 {state.get('status')} "
                       f"상한 {used_limit}자({whole_min}/{half_min})")
        report.append(f"제출: 상한 {used_limit}자 → 조각 {part_ids}, 감사 {len(audits)}줄 "
                      f"{audits[0].split(' cuts=', 1)[-1] if audits else ''}")


# 작업 159: 참고 구현(whynot-20261029 app/src/vpoc/compose.py STYLE·_cuts_video_prompt, live.py reference_lead) 원문을 옮겨 둔 글자.
_VB159_MULTI_SHOT = (
    "A multi-shot sequence of {n} shots edited like a TV drama, with a hard cut at the start of "
    "each new shot. Each shot keeps one framing and the camera stays almost still within the shot. "
    "The same characters, outfits and setting appear in every shot, and each character's hair color and "
    "clothing colors stay exactly as described above in every shot. Each person has exactly two hands; "
    "only the hands described in a shot are visible."
)
_VB159_STYLE_WEBTOON = ("Korean webtoon art style exactly as in the uploaded webtoon images: the same line work, "
                        "coloring, shading and character designs")
_VB159_STYLE_LIVE = ("Cinematic live-action film footage, photorealistic, natural skin texture, 35mm lens, soft natural light, "
                     "romance K-drama cinematography, soft glow, shallow depth of field, warm pastel color grading")
_VB159_LOCATION = "@Image{no} is the location (no people in it); keep this place, its background and light in every shot"
_VB159_VIDEO = ("@Video1 is the 3D previz: follow its camera, positions, cuts and timing exactly; "
                "replace each mannequin with its person")
_VB159_SHEET = "AI-generated turnaround sheet of a fictional character; match face/hair/build, clothes from the look line"
_VB159_SPOKEN = "spoken (audio only, never written on screen)"
# fix1: 애니 원작 패널 설명(STYLE 이 부르는 "the uploaded webtoon images", 옛 _take_prompt 와 같은 범위 표기).
_VB159_PANELS = "{refs} are the uploaded webtoon images (art style reference only)"
# 끔(VNEW_VIBE_PROMPT=False) 기준: 작업 159 전 _take_prompt 의 157 손 추출 통 테이크 sha(VNEW_FX 켬·4,000자, 157 검사 cast).
_VB159_SHA_OFF = {"anime": "057902b478b7da5372d374f99a11174b725b72d0bda8498c3f1ca93ce436ccf7",
                  "real": "df11aa7420e9ebdfdf429983c056cf08187f69ba6ba61e4129570e14f87850c9"}


def check_vnew_vibe_prompt_159() -> None:
    """작업 159 — 통 테이크 프롬프트 = video-vibecode 형식(_vibe_take_prompt, VNEW_VIBE_PROMPT 기본 켬). 가짜, 유료 0.

    (vb-a) 애니(157 손 추출 test3 모양): 140 고지 → 인물 handle+look → 컷 지시 단락(참고 원문 그대로) → Setting → Shot 1..6
           (who_in_shot·연기+닿는 연기·포즈·모든 대사 spoken (audio only …)) → @Image 설명(reference_lead 문구·시트 절) → @Video1
    (vb-b) 실사: STYLE live_action 원문·REAL_FX(눈물·옅은 홍조)·웹툰 낱말 없음(_assert_no_webtoon)·@Video1·애니와 같은 대사
    (vb-c) 감사: 조각 c01–c02·c03–c06 애니·실사 4,000자 안, lines_in_prompt = lines_in_conti, 모든 컷 연기
    (vb-d) 예산: 짧은 형은 style → background → assets → paragraph 순(앞부분만), 샷 문장은 그대로, 넘치면 157 조각으로 나눈다
    (vb-e) 끔: _take_prompt sha 그대로(작업 159 전 값), _take_payload 끔 = 지금 _take_prompt·패널 참고 그대로
    (vb-f) 흐름(가짜 fal Seedance): 애니·실사 제출 프롬프트가 vibe 형식, 실사 = Seedance + 프리비즈 영상 + [시트, 정면]×2 + 실사 장소,
           애니 = [웹툰 시트, 웹툰 정면]×2 + 웹툰 장소 + 원작 패널(fix1, 옛 _take_prompt 와 같은 패널·순서), 상한에 걸리면 패널부터 빠짐,
           제출마다 prompt_audit 1줄 줄 수 같음
    """
    import base64 as _b64  # noqa: PLC0415
    import hashlib as _hashlib  # noqa: PLC0415
    import traceback as _tb  # noqa: PLC0415

    sys.path.insert(0, str(ROOT / "app"))
    from src.vnew import generate as genmod  # noqa: PLC0415

    bad: list[str] = []
    report: list[str] = []

    def expect(group: str, got, want, what: str) -> None:
        if got != want:
            bad.append(f"({group}) {what}\n      결과 {got!r}\n      기대 {want!r}")

    def sha(text: str) -> str:
        return _hashlib.sha256(text.encode("utf-8")).hexdigest()

    def decode(uri) -> bytes:
        try:
            return _b64.b64decode(str(uri).split(",", 1)[1])
        except Exception:  # noqa: BLE001
            return b""

    a, b = _TC157_A, _TC157_B
    flat_cast = [{"name": b, "colorName": "blue", "frontNo": 1, "appearance": "", "voice": "",
                  "costume": "Black long-sleeve track top with a single white stripe down each sleeve"},
                 {"name": a, "colorName": "orange", "frontNo": 2, "appearance": "", "voice": "",
                  "costume": "Dark navy long-sleeve button-up dress shirt, collar open, worn untucked"}]
    flat_real = [dict(flat_cast[0], frontNo=2, sheetNo=1, refNos=[1, 2], look="real",
                      appearance="a Korean man in his 20s with tousled pale blonde hair and long sweeping bangs"),
                 dict(flat_cast[1], frontNo=4, sheetNo=3, refNos=[3, 4], look="real",
                      appearance="narrow half-lidded eyes and short charcoal-black hair swept back")]
    anime_cast = [dict(flat_cast[0], frontNo=2, sheetNo=1, refNos=[1, 2], look="webtoon",
                       appearance="Pale blonde tousled hair with long bangs, large grey eyes"),
                  dict(flat_cast[1], frontNo=4, sheetNo=3, refNos=[3, 4], look="webtoon",
                       appearance="Short swept-back black hair, narrow half-lidded eyes")]

    def kinds(text: str) -> list[str]:
        out = []
        for line in text.split("\n"):
            if line == genmod.REAL_REF_AI_NOTE:
                out.append("note")
            elif line.startswith((_VB159_STYLE_WEBTOON, _VB159_STYLE_LIVE, "Korean webtoon art style", "Photoreal live-action")):
                out.append("style")
            elif line.endswith("(keep exactly this look)."):
                out.append("look")
            elif line.startswith("A multi-shot sequence of "):
                out.append("paragraph")
            elif line.startswith("Setting (keep identical in every shot): "):
                out.append("setting")
            elif re.match(r"^Shot \d+ \(\d+-\d+s\), ", line):
                out.append("shot")
            elif line.startswith("@Image1 is "):
                out.append("labels")
            elif line.startswith(_VB159_VIDEO):
                out.append("video")
            else:
                out.append("?" + line[:40])
        return out

    def shots(text: str) -> list[str]:
        return [ln for ln in text.split("\n") if re.match(r"^Shot \d+ \(", ln)]

    try:
        # 작업 184: 이 157 테이크의 MCU · CU 한 사람 샷(cut-01 · 02 · 06 …)에 클로즈업 옷 단서가 붙고, vb-d 의 20자 여유는 184 짧은 단서가
        # 먼저 흡수한다 → 159 고정 글(who · 짧은 형 순서)은 184 를 끈 글로 본다(184 가 바꾸는 줄은 check_vnew_closeup_garment_184 cl-e).
        with _guard_real_llm() as llm_calls, _pin_vnew(VNEW_FX=True, VNEW_TAKE_PROMPT_MAX_CHARS=4000, VNEW_VIBE_PROMPT=True) as vset, \
                _is184_off():
            plan, take = _tc157_plan()
            ra, rb = genmod._romanize_name(a), genmod._romanize_name(b)  # noqa: SLF001
            vset.VNEW_TAKE_PROMPT_MAX_CHARS = 8000  # 통 테이크 원형(짧은 형 없음)을 본다
            full: dict[str, str] = {}
            audits: dict[str, dict] = {}
            for variant, cast in (("webtoon", anime_cast), ("real", flat_real)):
                audits[variant] = {}
                # fix1: 애니는 원작 패널 @Image6–8(장소 뒤). 실사에 패널 번호를 줘도 설명이 붙지 않아야 한다.
                full[variant] = genmod._vibe_take_prompt(plan, take, real=variant == "real", cast=cast,  # noqa: SLF001
                                                         location_no=5, panel_nos=[6, 7, 8], audit=audits[variant],
                                                         quiet=True)
            vset.VNEW_TAKE_PROMPT_MAX_CHARS = 4000

            # ================= (vb-a) 애니 순서·내용 =================
            text = full["webtoon"]
            lines = text.split("\n")
            want_kinds = ["note", "style", "look", "look", "paragraph", "setting"] + ["shot"] * 6 + ["labels", "video"]
            labels = next((ln for ln in lines if ln.startswith("@Image1 is ")), "")
            expect("vb-a", [kinds(text), lines[1], lines[2], lines[4], lines[5].startswith(
                "Setting (keep identical in every shot): Outdoors by a low metal railing"), audits["webtoon"].get("compact")],
                [want_kinds, _VB159_STYLE_WEBTOON + ", with Korean webtoon visual symbols.",
                 f"{rb}: Pale blonde tousled hair with long bangs, large grey eyes, wearing black long-sleeve track top with a "
                 "single white stripe down each sleeve (keep exactly this look).", _VB159_MULTI_SHOT.format(n=6), True, []],
                "애니 줄 순서(고지 → 화풍 → handle+look → 컷 지시 단락 원문 → Setting → Shot → @Image → @Video1)")
            # 작업 179: 애니 웹툰 시트(@Image1 · @Image3) 이름표 = 한 문장 시트 글(_SR179_SHEET_LABEL, 패널에 없는 각도는 시트에서) —
            # 옛 "@Image1 is X" + 맨 끝 시트 절 1번 대신. 정면(@Image2 · @Image4) · 장소 · 패널 글은 그대로.
            # 작업 180: 정면(@Image2 · @Image4) = 장면 옷 그림 없음 + look 줄에 옷 → 얼굴 · 머리만 꼬리(_FC180_FACE_ONLY),
            # fix1: 이름표 블록 끝 공통 옷 문장 1번(_FC180_SHARED).
            expect("vb-a", [labels, lines[-1]],
                   [_SR179_SHEET_LABEL.format(no=1, name=rb) + f" @Image2 is {rb}{_FC180_FACE_ONLY}; "
                    + _SR179_SHEET_LABEL.format(no=3, name=ra) + f" @Image4 is {ra}{_FC180_FACE_ONLY}; "
                    + _VB159_LOCATION.format(no=5)
                    + f"; {_VB159_PANELS.format(refs='@Image6–@Image8')}. {_FC180_SHARED}",
                    _VB159_VIDEO + f" (blue = {rb}, orange = {ra})."],
                   "@Image 설명 = reference_lead 문구(인물 → 장소 → 원작 패널(STYLE 의 uploaded webtoon images), 179 시트 글)·@Video1 줄")
            whos = {"cut-01": f"Only {ra} appears in this shot; {rb} is not visible. ",
                    "cut-02": f"Only {rb} appears in this shot; {ra} is not visible. ",
                    "cut-06": f"{rb} and {ra} (hands only) appear in this shot. "}
            per_shot = {}
            # 작업 173: cut-06(목덜미를 쓰다듬음 · 손 표기 other_neck)은 상대 얼굴 접촉 → 닿는 연기 · 포즈 절의 목 글이 턱 받침 글 1번이
            # 되고(같은 글 두 번은 닿는 연기를 뺌) Touch 줄이 붙는다(요구 2 · 3). 다른 컷의 닿는 연기는 그대로.
            # 작업 174: cut-06 은 "stroking … neck and nape" = 귀 · 목 쓰다듬기 종류 → 173 턱 들기 글이 종류와 어긋나 귀 뒤 손끝 글 1번 +
            # 귀 Touch 줄(요구 1). 같은 글 두 번이면 닿는 연기를 빼는 규칙은 그대로.
            lift173 = f"{ra}'s right hand lightly brushes behind {rb}'s ear with his fingertips"
            touch173 = genmod.FACE_TOUCH_LINES["ear"].rstrip(".")
            for k, (cid, line) in enumerate(zip(take["cutIds"], shots(text))):
                action = (audits["webtoon"].get("actions") or [""] * 6)[k]
                quotes = [f'{_VB159_SPOKEN}: "{q}"' for q in _TC157_QUOTES[cid]]
                contact_ok = (cid not in _TC157_CONTACT or _TC157_CONTACT[cid].rstrip(".") in line if cid != "cut-06"
                              else line.count("lightly brushes behind") == 1 and lift173 in line and touch173 in line
                              and "chin" not in line)
                per_shot[cid] = [line.startswith(f"Shot {k + 1} ("), whos.get(cid, "") in line, bool(action) and action in line,
                                 contact_ok, [(text.count(q), q in line) for q in quotes]]
            expect("vb-a", per_shot, {cid: [True, True, True, True, [(1, True)] * len(_TC157_QUOTES[cid])]
                                      for cid in take["cutIds"]},
                   "샷마다 번호·who_in_shot·연기·닿는 연기(174: cut-06 귀 뒤 손끝 + 귀 Touch 줄)·대사(spoken (audio only …)) 1번 제 샷 안")
            expect("vb-a", [f"{rb} (inner voice-over, lips closed), {_VB159_SPOKEN}:" in shots(text)[5],
                            lift173 in shots(text)[5] and f"{rb}'s neck" not in shots(text)[5],
                            f"{rb} (one continuous line that carries over the next cut" in shots(text)[2],
                            "TIMELINE" in text or "ASSETS:" in text],
                   [True, True, True, False], "속마음·148 포즈 절(174: cut-06 목 → 귀 뒤 손끝)·147 이어지는 말, 옛 TIMELINE/ASSETS 없음")

            # ================= (vb-b) 실사 =================
            real = full["real"]
            rs = shots(real)
            try:
                genmod._assert_no_webtoon(real)  # noqa: SLF001
                no_webtoon = True
            except Exception:  # noqa: BLE001
                no_webtoon = False
            expect("vb-b", [kinds(real), real.split("\n")[1], no_webtoon, "webtoon" in real.lower(),
                            f"tears run down {rb}'s cheeks only" in rs[2], f"a faint natural flush on {rb}'s cheeks only" in rs[5],
                            any(w in real for w in ("blush lines", "tear streams", "Webtoon-style", "visual symbols")),
                            real.split("\n")[-1].startswith(_VB159_VIDEO), _VB159_LOCATION.format(no=5) in real,
                            "uploaded webtoon image" in real,
                            [re.findall(r'"[^"]*"', ln) for ln in rs] == [re.findall(r'"[^"]*"', ln) for ln in shots(text)]],
                   [want_kinds, _VB159_STYLE_LIVE + ".", True, False, True, True, False, True, True, False, True],
                   "실사: 같은 줄 순서·STYLE live_action 원문·웹툰 낱말 없음·REAL_FX·@Video1·장소·패널 없음·애니와 같은 대사")

            # ================= (vb-c) 감사(조각 c01–c02·c03–c06, 4,000자) =================
            parts = [{"cutIds": ["cut-01", "cut-02"], "seconds": 8.0},
                     {"cutIds": ["cut-03", "cut-04", "cut-05", "cut-06"], "seconds": 15.0}]
            got_c, want_c = [], []
            for variant, cast in (("webtoon", anime_cast), ("real", flat_real)):
                for part in parts:
                    sub = genmod._part_take(plan, take, part)  # noqa: SLF001
                    audit: dict = {}
                    out = genmod._vibe_take_prompt(plan, sub, real=variant == "real", cast=cast, location_no=5,  # noqa: SLF001
                                                   panel_nos=[] if variant == "real" else [6, 7, 8], audit=audit, quiet=True)
                    got_c.append([audit.get("fits"), audit.get("linesInPrompt") == audit.get("linesInConti"),
                                  audit.get("actionsInPrompt"), len(shots(out))])
                    # 작업 179: 애니 시트 이름표 2개(인물마다 한 문장)가 길어져 애니 c03–c06 은 짧은 형 4단계 뒤에도 4,000자를
                    # 넘는다(4,058자) → 제출 쪽 157 나누기. 대사 · 연기 · 샷 줄 수는 그대로. 실사 · c01–c02 는 그대로 4,000자 안.
                    want_c.append([not (variant == "webtoon" and len(sub["cutIds"]) == 4), True, len(sub["cutIds"]),
                                   len(sub["cutIds"])])
                    report.append(f"{variant} {sub['cutIds'][0]}–{sub['cutIds'][-1]}: {genmod._prompt_len(out)}자 compact="  # noqa: SLF001
                                  f"{','.join(audit.get('compact') or []) or 'none'} 대사 {audit.get('linesInPrompt')}/"
                                  f"{audit.get('linesInConti')} 연기 {audit.get('actionsInPrompt')}/{audit.get('cuts')}")
            expect("vb-c", got_c, want_c, "조각마다 4,000자 안·대사 줄 수 같음·모든 컷 연기·샷 줄 수 = 컷 수")

            # ================= (vb-d) 예산 =================
            order = list(genmod.VIBE_COMPACT_ORDER)
            got_d = []
            vset.VNEW_TAKE_PROMPT_MAX_CHARS = 8000  # 상한 = caps.promptMaxLength(통 테이크 원형보다 20자 작게 · 3,000 · 1,500)
            for cap in (genmod._prompt_len(text) - 20, 3000, 1500):  # noqa: SLF001
                audit = {}
                with _LogCapture() as logs:
                    out = genmod._vibe_take_prompt(plan, take, real=False, cast=anime_cast, location_no=5,  # noqa: SLF001
                                                   panel_nos=[6, 7, 8], caps={"promptMaxLength": cap}, audit=audit)
                steps = next((m.rsplit("steps=", 1)[-1] for m in logs.messages("vnew.gen.take_prompt builder=vibe")), "")
                compact = audit.get("compact") or []
                got_d.append([compact == order[:len(compact)], bool(compact), shots(out) == shots(text),
                              audit.get("fits") == (genmod._prompt_len(out) <= cap),  # noqa: SLF001
                              steps.split(",") == [s + "Compact" for s in compact] + ([] if audit.get("fits") else ["overBudget"]),
                              audit.get("linesInPrompt") == audit.get("linesInConti") == 9])
            expect("vb-d", got_d, [[True] * 6] * 3, "짧은 형은 style → background → assets → paragraph 앞부분만·샷 문장 그대로·로그 단계")
            vset.VNEW_TAKE_PROMPT_MAX_CHARS = 4000
            expect("vb-d", [genmod._prompt_len(text) > 4000, order[-1]], [True, "paragraph"],  # noqa: SLF001
                   "통 테이크 원형은 4,000자를 넘고 head 단락이 마지막으로 줄어든다")

            def probe(sub_take: dict) -> dict:
                result: dict = {}
                genmod._vibe_take_prompt(plan, sub_take, real=False, cast=anime_cast, location_no=5,  # noqa: SLF001
                                         panel_nos=[6, 7, 8], caps={"promptMaxLength": 1500}, audit=result, quiet=True)
                return result

            split_parts = genmod._prompt_split_parts(plan, take, [], {"audit": probe(take), "probe": probe})  # noqa: SLF001
            probes = [probe(genmod._part_take(plan, take, p)) for p in split_parts]  # noqa: SLF001
            expect("vb-d", [len(split_parts) >= 2, [c for p in split_parts for c in p["cutIds"]],
                            all(pr.get("fits") or len(p["cutIds"]) == 1 for p, pr in zip(split_parts, probes)),
                            all(pr.get("linesInPrompt") == pr.get("linesInConti") for pr in probes)],
                   [True, take["cutIds"], True, True], f"1,500자 → 157 조각 {[p['cutIds'] for p in split_parts]}")
            report.append(f"통 테이크 원형 {genmod._prompt_len(text)}자 → 4,000자: 짧은 형 4단계 후 조각, "  # noqa: SLF001
                          f"1,500자 → 조각 {[p['cutIds'] for p in split_parts]}")

            # ================= (vb-e) 끔: _take_prompt sha 그대로 =================
            vset.VNEW_VIBE_PROMPT = False
            with _LogCapture():
                off_w = genmod._take_prompt(plan, take, cast=flat_cast, panel_nos=[3, 4, 5], location_no=6)  # noqa: SLF001
                off_r = genmod._take_prompt(plan, take, cast=flat_real, panel_nos=[], location_no=5, variant="real")  # noqa: SLF001
            expect("vb-e", [sha(off_w), sha(off_r)], [_VB159_SHA_OFF["anime"], _VB159_SHA_OFF["real"]],
                   "끔: 157 손 추출 통 테이크 _take_prompt sha = 작업 159 전")
            if llm_calls:
                bad.append(f"가짜가 아닌 LLM 호출: {llm_calls}")

        # ================= (vb-f) 흐름 =================
        owner = "tester"
        with _guard_real_llm() as llm_calls, _LogCapture() as logs, _LrEnv(owner) as env, _pin_vnew(
                VNEW_FX=False, VNEW_CASTING=True, VNEW_TAKE_REAL=True, VNEW_GEN_PARALLEL=1, POLL_INTERVAL_S=0,
                VNEW_TAKE_AUDIO=True, VNEW_TAKE_RESOLUTION="480p", VNEW_TEXT_CHECK=False, VNEW_REAL_TAKE_MODEL=_LR_ENDPOINT,
                VNEW_VIBE_PROMPT=True, VNEW_TAKE_PROMPT_MAX_CHARS=4000,
                VNEW_REAL_COSTUME_REF=False) as vset:  # 작업 160: 159 기대값은 [시트, 정면] 그대로 — 장면 옷 편집은 160 검사가 본다
            # 상한 4,000자를 이 검사 안에서 고정한다(_tc157_submit 은 fix1 부터 finally 로 되돌리지만, 순서에 기대지 않는다).
            for cid in ("ch1", "ch2"):
                env.chars[cid]["variants"]["real"]["sheetKey"] = f"rs-{cid}"
                env.chars[cid]["variants"]["webtoon"]["sheetKey"] = f"ws-{cid}"
            env.blobs.update({"rs-ch1": b"RS1", "rs-ch2": b"RS2", "ws-ch1": b"WS1", "ws-ch2": b"WS2"})
            client = env.client()
            pid = "prj_vb159"
            env.make_plan(pid, [{"id": "s1", "cutIds": ["c1", "c2"], "seconds": 8}])
            since = len(env.requests)
            client.post(f"/api/vnew/p/{pid}/generate", json={"confirmUsd": genmod.estimate(env.plan(pid))["totalUsd"]})
            g = env.drive(pid)
            anime_reqs = env.requests[since:]
            since = len(env.requests)
            client.post(f"/api/vnew/p/{pid}/generate/real", json={"confirmUsd": genmod.real_estimate(g)["usd"]})
            env.drive(pid)
            real_reqs = env.requests[since:]

            def view(req: dict) -> dict:
                payload = req["payload"]
                prompt = str(payload.get("prompt") or "")
                return {"seedance": str(req["url"]).endswith(_LR_ENDPOINT),
                        "video": [b"PREVIZ-REC-s1" in decode(u) for u in payload.get("video_urls") or []],
                        "images": [decode(u) for u in payload.get("image_urls") or []],
                        "note": prompt.startswith(genmod.REAL_REF_AI_NOTE + "\n"), "videoLine": _VB159_VIDEO in prompt,
                        "location": _VB159_LOCATION.format(no=5) in prompt, "sheet": _VB159_SHEET in prompt,
                        "live": _VB159_STYLE_LIVE in prompt, "webtoonStyle": _VB159_STYLE_WEBTOON in prompt,
                        "webtoonWord": "webtoon" in prompt.lower(), "old": "TIMELINE" in prompt or "ASSETS:" in prompt,
                        "sheet179": _SR179_SHEET_TAIL in prompt}

            def pairs(images: list[bytes], sheet: bytes, front: bytes) -> bool:
                people = [tuple(images[i:i + 2]) for i in range(0, len(images) - 1, 2)]
                return sorted(people) == sorted([(sheet + b"1", front + b"1"), (sheet + b"2", front + b"2")])

            got_f = [[view(r)["seedance"], view(r)["video"], view(r)["note"], view(r)["videoLine"], view(r)["location"],
                      view(r)["sheet"], view(r)["live"], view(r)["webtoonStyle"], view(r)["webtoonWord"], view(r)["old"],
                      view(r)["images"][4:], pairs(view(r)["images"][:4], *((b"RS", b"RF") if r in real_reqs else (b"WS", b"WF"))),
                      _VB159_PANELS.format(refs="@Image6–@Image7") in str(r["payload"].get("prompt") or ""), view(r)["sheet179"]]
                     for r in anime_reqs + real_reqs]
            # fix1: 애니 = 신원 참고 → 장소 → 원작 패널(옛 _take_prompt 와 같은 _segment_panel_jpegs 순서), 실사 = 패널 없음.
            # 작업 179: 애니 시트 이름표 = 179 시트 글(sheet179 True) → 옛 시트 절(sheet)은 애니에서 False. 실사는 그대로(옛 절, 179 글 없음).
            want_f = [[True, [True], True, True, True, False, False, True, True, False, [b"LOC-WB", b"PANEL1", b"PANEL2"], True,
                       True, True],
                      [True, [True], True, True, True, True, True, False, False, False, [b"LOC-RB"], True, False, False]]
            expect("vb-f", got_f, want_f, "애니·실사 제출: Seedance·프리비즈 영상·vibe 줄·[시트, 정면]×2 + 장소 (+ 애니 원작 패널)")

            # fix1: 상한 — 패널부터 빠지고 신원 참고·장소는 남는다.
            plan_c = env.plan(pid)
            take_c = genmod._take_units(plan_c)[0]  # noqa: SLF001
            got_cap = {}
            for cap in (10, 6, 5, 3):
                built = genmod._vibe_take_payload(owner, pid, plan_c, take_c, dict(_LR_CAPS, imageListMax=cap),  # noqa: SLF001
                                                  variant="webtoon", fallback_step=0, soften=False, continuity=None,
                                                  no_text=False)
                got_cap[cap] = ([bytes(i) for i in built["imageUrls"]], built["locationNo"], built["panelNos"])
            want_cap = {cap: (imgs, loc, panels) for cap, imgs, loc, panels in (
                (10, [b"WS1", b"WS2", b"WF1", b"WF2", b"LOC-WB", b"PANEL1", b"PANEL2"], 5, [6, 7]),
                (6, [b"WS1", b"WS2", b"WF1", b"WF2", b"LOC-WB", b"PANEL1"], 5, [6]),
                (5, [b"WS1", b"WS2", b"WF1", b"WF2", b"LOC-WB"], 5, []),
                (3, [b"WS1", b"WS2", b"LOC-WB"], 3, []))}

            def norm(images: list[bytes]) -> list[bytes]:
                # 인물 순서(등장 순)는 계획이 정한다 — 신원 참고는 집합으로, 장소·패널은 자리로 본다.
                n = len([i for i in images if i[:2] in (b"WS", b"WF")])
                return sorted(images[:n]) + images[n:]

            expect("vb-f", {k: (norm(v[0]), v[1], v[2]) for k, v in got_cap.items()},
                   {k: (norm(v[0]), v[1], v[2]) for k, v in want_cap.items()},
                   "상한 10·6·5·3: 패널부터 빠지고 신원 참고·장소는 남는다")
            audit_logs = logs.messages(f"vnew.gen.prompt_audit pid={pid}")
            counts = [(re.search(r"lines_in_conti=(\d+)", m).group(1), re.search(r"lines_in_prompt=(\d+)", m).group(1))
                      for m in audit_logs]
            expect("vb-f", [len(audit_logs), all(x == y for x, y in counts), any(" variant=real " in m for m in audit_logs)],
                   [2, True, True], f"제출마다 prompt_audit 1줄·줄 수 같음 {counts}")

            # (vb-e) 끔: _take_payload = 지금 _take_prompt·패널 참고(작업 159 전 경로 그대로).
            vset.VNEW_VIBE_PROMPT = False
            plan_f = env.plan(pid)
            take_f = genmod._take_units(plan_f)[0]  # noqa: SLF001
            built = genmod._take_payload(owner, pid, plan_f, take_f, dict(_LR_CAPS))  # noqa: SLF001
            direct = genmod._take_prompt(plan_f, take_f, cast=built["cast"], panel_nos=built["panelNos"],  # noqa: SLF001
                                         location_no=built["locationNo"], caps=dict(_LR_CAPS))
            expect("vb-e", [built["prompt"] == direct, b"PANEL1" in [bytes(i) for i in built["imageUrls"]],
                            built["prompt"].startswith("STYLE: "), _VB159_VIDEO in built["prompt"]],
                   [True, True, True, False], "끔: _take_payload 가 지금 _take_prompt·원작 패널 참고 그대로")
            if llm_calls:
                bad.append(f"가짜가 아닌 LLM 호출: {llm_calls}")
            report.append(f"제출: 애니 {len(anime_reqs)}건·실사 {len(real_reqs)}건, 감사 {len(audit_logs)}줄")
    except Exception:  # noqa: BLE001
        bad.append("작업 159 검사 예외\n" + _tb.format_exc())
    if bad:
        fail("작업 159 video-vibecode 테이크 프롬프트 검사 실패\n  " + "\n  ".join(bad))
    else:
        ok("작업 159 vibe 테이크 프롬프트 (vb-a)애니 순서·컷 지시 원문·who_in_shot·연기·닿는 연기·대사 (vb-b)실사 live_action·REAL_FX·"
           "웹툰 없음·@Video1 (vb-c)감사 줄 수 (vb-d)짧은 형 순서·샷 그대로·조각 (vb-e)끔 sha·_take_payload 그대로 "
           "(vb-f)Seedance·프리비즈 영상·시트+정면·장소·애니 원작 패널(상한 때 패널부터 빠짐)")
        for line in report:
            print(f"       159: {line}")


# 작업 160: test3 실측 장면 옷(take1·take2 패널 읽기가 같은 사람·같은 장소에서 다른 옷을 골랐다).
_CR160_TRACK = "Black long-sleeve track top with a single white stripe down each sleeve"
_CR160_ZIP = "black zip-up track jacket/hoodie with a high collar"
_CR160_NAVY = "Dark navy long-sleeve button-up dress shirt, collar open, worn untucked"
_CR160_CREW = "plain black top with a crew neckline"


def check_vnew_real_costume_160() -> None:
    """작업 160 — 장소마다 인물 옷 1벌(_scene_costume)·장면 옷 신원 참고(메모리만)·컷 단위 Kling 이어짐. 가짜, 유료 0.

    (cs-a) 옷: test3 모양(take1 패널 "track top", take2 패널 "zip-up track jacket", 같은 사람·장소)에서 실사·애니 vibe 테이크·조각·
           155 의상 고정·옛 _take_prompt·시작 그림이 모두 한 벌(3:3 동점 → 앞 컷 take1). 다수결(4:2)·동점 앞 컷·장소별·콘티 우선·수정 우선
    (cs-b) 신원 참고: 실사 회차(테이크 2개) = 보이는 인물당 edit 1번(입력 실사 정면·문구·세로 크기), 정면 자리 = 편집 바이트·
           "@ImageN is X in this scene's clothes"·시트 절 "clothes come from @ImageN", 원장 호출마다 1줄(image·$0.04),
           저장 0(STORE put·blob·JSON 에 편집 바이트 없음), 애니 회차 호출 0 / 실패 → 지금 참고(RF)·이름표 없음·원장 0·다시 부르지 않음
    (cs-c) Kling 이어짐(Seedance 0·1단계 거절 → 2단계): 컷 2 시작 그림 참고 맨 뒤 = 컷 1 시작 그림 + REAL_STILL_PREV, 모든 시작 그림·
           Kling 프롬프트에 시간대 문장, 시작 그림 넓히지 않기, 시작 그림 정면 자리 = 편집 그림(같은 회차 edit 2번뿐), 밤 콘티 → Night
    """
    import base64 as _b64  # noqa: PLC0415
    import copy as _copy  # noqa: PLC0415
    import traceback as _tb  # noqa: PLC0415

    sys.path.insert(0, str(ROOT / "app"))
    from src.vnew import generate as genmod  # noqa: PLC0415
    from src.vpoc.errors import VpocError  # noqa: PLC0415

    bad: list[str] = []
    report: list[str] = []

    def expect(group: str, got, want, what: str) -> None:
        if got != want:
            bad.append(f"({group}) {what}\n      결과 {got!r}\n      기대 {want!r}")

    def decode(uri) -> bytes:
        try:
            return _b64.b64decode(str(uri).split(",", 1)[1])
        except Exception:  # noqa: BLE001
            return b""

    try:
        # ================= (cs-a) 장소마다 옷 1벌 =================
        with _guard_real_llm() as llm_calls, _LogCapture(), _pin_vnew(VNEW_FX=True, VNEW_TAKE_PROMPT_MAX_CHARS=8000):
            a, b = _TC157_A, _TC157_B
            plan, take = _tc157_plan()
            ids = list(take["cutIds"])
            loc = genmod._take_location(plan, take)  # noqa: SLF001
            t1 = dict(genmod._part_take(plan, take, {"cutIds": ids[:3], "seconds": 12.0}), id="take1")  # noqa: SLF001
            t2 = dict(genmod._part_take(plan, take, {"cutIds": ids[3:], "seconds": 11.0}), id="take2")  # noqa: SLF001
            notes = {"k1": {b: {"costumeEn": _CR160_TRACK, "voiceEn": ""}, a: {"costumeEn": _CR160_NAVY, "voiceEn": ""}},
                     "k2": {b: {"costumeEn": _CR160_ZIP, "voiceEn": ""}, a: {"costumeEn": _CR160_CREW, "voiceEn": ""}}}

            def with_map(mapping: dict) -> dict:
                out = _copy.deepcopy(plan)
                out["previz"]["castNotes"] = _copy.deepcopy(notes)
                out["previz"]["castNotesCuts"] = mapping
                return out

            p3 = with_map({c: ("k1" if c in ids[:3] else "k2") for c in ids})  # test3: take1 3컷 · take2 3컷(동점)

            def cast_for(key: str, real: bool) -> list[dict]:
                look = "real" if real else "webtoon"
                return [{"name": b, "colorName": "blue", "frontNo": 2, "sheetNo": 1, "refNos": [1, 2], "look": look,
                         "appearance": "", "voice": "", "costume": notes[key][b]["costumeEn"]},
                        {"name": a, "colorName": "orange", "frontNo": 4, "sheetNo": 3, "refNos": [3, 4], "look": look,
                         "appearance": "", "voice": "", "costume": notes[key][a]["costumeEn"]}]

            want = {b: genmod._scene_outfit_text(_CR160_TRACK), a: genmod._scene_outfit_text(_CR160_NAVY)}  # noqa: SLF001
            other = {b: genmod._scene_outfit_text(_CR160_ZIP), a: genmod._scene_outfit_text(_CR160_CREW)}  # noqa: SLF001
            prompts: dict[str, str] = {}
            part = genmod._part_take(p3, t2, {"cutIds": ids[4:], "seconds": 7.0})  # noqa: SLF001
            for real in (True, False):
                tag = "real" if real else "anime"
                for name, sub, key in (("take1", t1, "k1"), ("take2", t2, "k2"), ("part", part, "k2")):
                    prompts[f"vibe-{tag}-{name}"] = genmod._vibe_take_prompt(  # noqa: SLF001
                        p3, sub, real=real, cast=cast_for(key, real), location_no=5, quiet=True)
                prompts[f"vibe-{tag}-lock"] = genmod._vibe_take_prompt(  # noqa: SLF001
                    p3, t2, real=real, cast=cast_for("k2", real), location_no=5, anchor=True, quiet=True)
                for name, sub, key in (("take1", t1, "k1"), ("take2", t2, "k2")):
                    prompts[f"old-{tag}-{name}"] = genmod._take_prompt(  # noqa: SLF001
                        p3, sub, cast=cast_for(key, real), panel_nos=[], location_no=5, variant="real" if real else "webtoon",
                        quiet=True)
                prompts[f"old-{tag}-lock"] = genmod._take_prompt(  # noqa: SLF001
                    p3, t2, cast=cast_for("k2", real), panel_nos=[], location_no=5, variant="real" if real else "webtoon",
                    anchor={}, quiet=True)
            got_a = {}
            for tag, text in prompts.items():
                low = text.lower()
                got_a[tag] = [want[b][:40].lower() in low, want[a][:40].lower() in low,
                              other[b][:30].lower() in low, other[a].lower() in low]
            expect("cs-a", got_a, {tag: [True, True, False, False] for tag in prompts},
                   "모든 테이크·조각·155 고정·실사/애니·옛 경로가 한 벌(take1 패널 읽기, 3:3 동점 앞 컷)만 쓴다")
            expect("cs-a", [genmod._costume_lock_tail(want[b]) in prompts["vibe-real-lock"],  # noqa: SLF001
                            genmod._costume_lock("Yeouijun", want[b]) in prompts["old-real-lock"]],  # noqa: SLF001
                   [True, True], "155 의상 고정 구절도 같은 옷")
            stills = {cid: genmod._cut_still_prompt(p3, {"cutId": cid}, [("blue", b, 2), ("orange", a, 3)], True,  # noqa: SLF001
                                                    source="anime", outfits={n: v["costumeEn"] for n, v in notes[k].items()})
                      for cid, k in (("cut-02", "k1"), ("cut-05", "k2"))}
            # 작업 183 fix1: OUTFITS 글 = _wears(옷 첫 낱말 머리글자 내림)
            expect("cs-a", {cid: [genmod._wears(b, want[b]) in p, genmod._wears(a, want[a]) in p, other[b] in p]  # noqa: SLF001
                            for cid, p in stills.items()},
                   {"cut-02": [True, True, False], "cut-05": [True, True, False]}, "시작 그림 OUTFITS 도 같은 옷")
            # 다수결·동점·장소·콘티·수정
            p_major = with_map({c: ("k2" if c in ids[:2] else "k1") for c in ids})  # k2 앞 2컷, k1 뒤 4컷
            p_tie = with_map({c: ("k2" if c in ids[:3] else "k1") for c in ids})  # k2 가 앞 3컷(동점)
            p_loc = with_map({c: ("k1" if c in ids[:3] else "k2") for c in ids})
            p_loc["conti"]["cuts"][5]["locationEn"] = "Inside a bright convenience store"
            p_conti = _copy.deepcopy(p3)
            p_conti["conti"]["cuts"][4]["characters"][1]["outfitEn"] = "grey hooded sweatshirt and faded jeans"
            p_over = _copy.deepcopy(p_conti)
            p_over.setdefault("input", {})["castOverrides"] = {b: {"costume": "white cable-knit sweater"}}
            sc = genmod._scene_costume  # noqa: SLF001
            expect("cs-a", [sc(p_major, b, loc), sc(p_tie, b, loc), sc(p_loc, b, loc),
                            sc(p_loc, b, "Inside a bright convenience store"), sc(p_conti, b, loc), sc(p_over, b, loc),
                            sc(plan, b, loc, fallback=_CR160_ZIP)],
                   [want[b], other[b], want[b], other[b], "grey hooded sweatshirt and faded jeans", "white cable-knit sweater",
                    other[b]],
                   "다수결(4:2)·동점 앞 컷·장소별·콘티 우선·수정 우선·읽기 없으면 fallback")
            report.append(f"장면 옷: {b} = {want[b]!r} / {a} = {want[a]!r} (프롬프트 {len(prompts)}개·시작 그림 2개)")
            if llm_calls:
                bad.append(f"가짜가 아닌 LLM 호출: {llm_calls}")

        # ================= (cs-b)(cs-c) 실사 회차 흐름 =================
        owner = "tester"
        kling = "fal-ai/kling-video/v3/pro/image-to-video"
        kling_caps = {"promptField": "prompt", "startImageField": "start_image_url", "durations": [5, 10],
                      "durationAsString": True, "durationValues": {"5": "5", "10": "10"}, "sendDuration": True,
                      "aspectRatios": ["16:9"], "available": True}
        likeness_raw = "The images or videos provided may contain likenesses of real people or other private information."
        with _guard_real_llm() as llm_calls, _LogCapture() as logs, _LrEnv(owner) as env, _pin_vnew(
                VNEW_FX=False, VNEW_CASTING=True, VNEW_TAKE_REAL=True, VNEW_GEN_PARALLEL=1, POLL_INTERVAL_S=0,
                VNEW_TAKE_AUDIO=True, VNEW_TAKE_RESOLUTION="480p", VNEW_TEXT_CHECK=False, VNEW_REAL_TAKE_MODEL=_LR_ENDPOINT,
                VNEW_VIBE_PROMPT=True, VNEW_TAKE_PROMPT_MAX_CHARS=4000, VNEW_TAKE_MAX_SECONDS=4,
                VNEW_TAKE_REAL_LIKENESS_LADDER=True, VNEW_TAKE_REAL_KLING_MODEL=kling, VNEW_REAL_CUT_QA=False,
                VNEW_REAL_COSTUME_REF=True) as vset:
            for cid in ("ch1", "ch2"):
                env.chars[cid]["variants"]["real"]["sheetKey"] = f"rs-{cid}"
            env.blobs.update({"rs-ch1": b"RS1", "rs-ch2": b"RS2"})
            prefix_id = genmod.vpoc_settings.FAL_ID_PREFIX
            seed_find = genmod.vpoc_fal.find
            env.set(genmod.vpoc_fal, "find", lambda m: {"id": prefix_id + kling, "endpointId": kling, "caps": dict(kling_caps)}
                    if str(m) == prefix_id + kling else seed_find(m))
            edits: list[dict] = []
            mode = {"fail": False}

            def fake_edit(prompt, front, *, size):
                edits.append({"prompt": prompt, "front": bytes(front), "size": size})
                if mode["fail"]:
                    raise VpocError("vnew.generate.costume_ref", "HTTP500", "edit failed", 502)
                return b"COSTUME-" + bytes(front)

            env.set(genmod, "_seedream_costume", fake_edit)
            stills: list[dict] = []
            env.set(genmod, "_seedream", lambda prompt, refs, *, size: stills.append(
                {"prompt": prompt, "refs": [bytes(r) for r in refs]}) or b"STILL%d" % len(stills))
            env.set(genmod, "_cut_first_frame", lambda mp4, start: b"FRAME@%.1f" % float(start))
            env.set(genmod, "_trim_clip", lambda mp4, seconds: b"TRIM%.1f:" % float(seconds) + bytes(mp4))
            puts: list[tuple[str, bytes]] = []
            base_put = env.store.put_bytes

            def put(key, body, content_type, *, bucket=""):
                puts.append((str(key), bytes(body)))
                return base_put(key, body, content_type, bucket=bucket)

            env.set(env.store, "put_bytes", put)
            policy = {"reject": lambda req: False}
            base_fal = env._fal  # noqa: SLF001

            def fal_request(method, url, payload=None, *, where=""):
                rid = url.split("/requests/", 1)[-1].split("/", 1)[0]
                req = next((r for r in env.requests if r["rid"] == rid), None)
                if method == "GET" and not url.endswith("/status") and req and policy["reject"](req):
                    raise VpocError("fal.poll", "HTTP422", likeness_raw, 502)
                return base_fal(method, url, payload, where=where)

            env.set(env.falmod, "_request", fal_request)
            client = env.client()

            def seedance_real(req) -> bool:
                # vibe 실사 프롬프트는 _LrEnv 의 옛 STYLE 머리로 실사를 가르지 않는다 → 실사 회차 뒤 요청만 이 함수로 본다.
                return req["url"].endswith(_LR_ENDPOINT)

            def run_real(pid: str, segments: list[dict], reject: bool = False) -> dict:
                env.make_plan(pid, segments)
                pre = len(edits)
                client.post(f"/api/vnew/p/{pid}/generate", json={"confirmUsd": genmod.estimate(env.plan(pid))["totalUsd"]})
                g = env.drive(pid)
                out = {"animeEdits": len(edits) - pre, "since": len(env.requests), "led": len(env.ledger), "e0": len(edits),
                       "s0": len(stills)}
                real_rids = lambda req: req in env.requests[out["since"]:]  # noqa: E731
                policy["reject"] = (lambda req: seedance_real(req) and real_rids(req)) if reject else (lambda req: False)
                client.post(f"/api/vnew/p/{pid}/generate/real", json={"confirmUsd": genmod.real_estimate(g)["usd"]})
                env.drive(pid)
                policy["reject"] = lambda req: False
                out["reqs"] = env.requests[out["since"]:]
                out["edits"] = edits[out["e0"]:]
                out["stills"] = stills[out["s0"]:]
                out["costumeLedger"] = [e for e in env.ledger[out["led"]:]
                                        if e.get("model") == vset.VNEW_REAL_COSTUME_REF_MODEL]
                out["plan"] = env.plan(pid)
                return out

            two_takes = [{"id": "s1", "cutIds": ["c1"], "seconds": 4}, {"id": "s2", "cutIds": ["c2"], "seconds": 4}]
            office = "A closed principal's office"

            # ---- (cs-b) Seedance 성공, 테이크 2개 ----
            ra = run_real("prj_cr_a", two_takes)
            costume_of = {n: genmod._scene_costume(ra["plan"], n, office) for n in ("에이", "비")}  # noqa: SLF001
            seeds = [r for r in ra["reqs"] if seedance_real(r)]
            got_b = {"animeEdits": ra["animeEdits"], "edits": len(ra["edits"]),
                     "fronts": sorted(e["front"] for e in ra["edits"]),
                     "prompts": sorted(e["prompt"] for e in ra["edits"]),
                     "size": {e["size"] for e in ra["edits"]}, "takes": len(seeds)}
            want_b = {"animeEdits": 0, "edits": 2, "fronts": [b"RF1", b"RF2"],
                      "prompts": sorted(genmod.REAL_COSTUME_REF_PROMPT.format(costume=c) for c in costume_of.values()),
                      "size": {genmod.vnew_settings.FRONT_SIZE}, "takes": 2}
            expect("cs-b", got_b, want_b, "실사 회차(테이크 2개) = 보이는 인물당 edit 1번·실사 정면 입력·문구·세로 크기")
            expect("cs-b", [genmod.REAL_COSTUME_REF_PROMPT.startswith("Same person, same face and hair, now wearing {costume}"),
                            all(c for c in costume_of.values())], [True, True], "edit 문구·장면 옷 있음")
            per_req = []
            for req in seeds:
                images = [decode(u) for u in req["payload"].get("image_urls") or []]
                prompt = str(req["payload"].get("prompt") or "")
                row = []
                for rf, rs, ko in ((b"RF1", b"RS1", "에이"), (b"RF2", b"RS2", "비")):
                    cno = images.index(b"COSTUME-" + rf) + 1 if b"COSTUME-" + rf in images else 0
                    sno = images.index(rs) + 1 if rs in images else 0
                    handle = genmod._romanize_name(ko)  # noqa: SLF001
                    row.append([bool(cno), rf in images, bool(sno),
                                genmod.REAL_COSTUME_REF_LABEL.format(no=cno, name=handle) in prompt,
                                f"@Image{sno}: " + genmod.VIBE_SHEET_COSTUME_CLAUSE.format(no=cno) + "." in prompt,
                                f"wearing {costume_of[ko][:1].lower() + costume_of[ko][1:]}" in prompt])
                per_req.append(row)
            expect("cs-b", per_req, [[[True, False, True, True, True, True]] * 2] * 2,
                   "테이크마다 정면 자리 = 편집 바이트(실사 정면 없음)·시트 그대로·이름표·시트 절 clothes come from·look 줄 같은 옷")
            expect("cs-b", [len(ra["costumeLedger"]), {(e.get("kind"), e.get("units"), e.get("usd")) for e in ra["costumeLedger"]}],
                   [2, {("image", 1, float(genmod.vnew_settings.LOCATION_IMAGE_USD))}], "원장: edit 호출마다 1줄(image·장당)")
            stored = [k for k, body in puts if b"COSTUME-" in body] + [
                k for k, body in env.store.blobs.items() if isinstance(body, (bytes, bytearray)) and b"COSTUME-" in body]
            expect("cs-b", [stored, "COSTUME-" in repr(env.store.json), genmod.STORE is env.store],
                   [[], False, True], "편집 그림은 저장하지 않는다(STORE put·blob·JSON 0)")
            expect("cs-b", any("vnew.gen.costume_ref pid=prj_cr_a run=1 made=2 failed=0 stored=0" in m
                               for m in logs.messages("vnew.gen.costume_ref")), True, "로그 made=2 stored=0")

            # ---- (cs-b) edit 실패 → 지금 참고 ----
            mode["fail"] = True
            rc = run_real("prj_cr_c", two_takes)
            mode["fail"] = False
            seeds_c = [r for r in rc["reqs"] if seedance_real(r)]
            got_fail = [len(rc["edits"]), len(rc["costumeLedger"]), len(seeds_c),
                        [[b"RF1" in [decode(u) for u in r["payload"].get("image_urls") or []],
                          b"RF2" in [decode(u) for u in r["payload"].get("image_urls") or []],
                          "in this scene's clothes" in str(r["payload"].get("prompt") or "")] for r in seeds_c],
                        any("failed=2" in m for m in logs.messages("vnew.gen.costume_ref pid=prj_cr_c"))]
            expect("cs-b", got_fail, [2, 0, 2, [[True, True, False]] * 2, True],
                   "edit 실패: 인물당 1번만 시도·원장 0·지금 참고(실사 정면)·이름표 없음")

            # ---- (cs-c) Seedance 0·1단계 거절 → 컷 단위 Kling(테이크 1개·컷 2개) ----
            rb = run_real("prj_cr_b", [{"id": "s1", "cutIds": ["c1", "c2"], "seconds": 8}], reject=True)
            klings = [r["payload"] for r in rb["reqs"] if r["url"].endswith("/" + kling)]
            day = genmod._real_time_sentence(rb["plan"])  # noqa: SLF001
            s1, s2 = (rb["stills"] + [{"prompt": "", "refs": []}] * 2)[:2]
            first_out = b"STILL%d" % (rb["s0"] + 1)
            got_c = {"stills": len(rb["stills"]), "klings": len(klings), "edits": len(rb["edits"]),
                     "prevRef": [first_out in s1["refs"], s2["refs"][-1:] == [first_out]],
                     "prevLine": [genmod.REAL_STILL_PREV.format(no=len(s2["refs"])) in s2["prompt"],
                                  "the previous shot" in s1["prompt"]],
                     "time": [day in s1["prompt"], day in s2["prompt"], all(day in str(k.get("prompt") or "") for k in klings)],
                     "noWiden": [genmod.REAL_STILL_NO_WIDEN in s1["prompt"], genmod.REAL_STILL_NO_WIDEN in s2["prompt"]],
                     "costumeRef": [all(b"COSTUME-" + rf in s["refs"] and rf not in s["refs"] for rf in (b"RF1", b"RF2"))
                                    for s in (s1, s2)],
                     "label": [all(f"is {n} in this scene's clothes." in s["prompt"] for n in ("에이", "비")) for s in (s1, s2)],
                     "sheetClothes": ["clothes come from Image" in s["prompt"] for s in (s1, s2)]}
            want_c = {"stills": 2, "klings": 2, "edits": 2, "prevRef": [False, True], "prevLine": [True, False],
                      "time": [True, True, True], "noWiden": [True, True], "costumeRef": [True, True], "label": [True, True],
                      "sheetClothes": [True, True]}
            expect("cs-c", got_c, want_c, "컷 2 시작 그림 = 컷 1 시작 그림 참고·문장, 시간대·넓히지 않기, 정면 자리 = 편집 그림(edit 2번뿐)")
            # 작업 161: 기대값 변경 — 낮 문장을 분명하게 바꿨다(지시: "Bright daytime, blue sky, no dusk, no night, no sunset light.").
            expect("cs-c", day, "Bright daytime, blue sky, no dusk, no night, no sunset light.", "낮 콘티 → 낮 문장")
            night = _copy.deepcopy(rb["plan"])
            night["script"]["setting"]["timeKo"] = "밤"
            kl_night = genmod._segment_prompt(night, {"cutIds": ["c1"]}, first_segment=True, real=True)  # noqa: SLF001
            st_night = genmod._cut_still_prompt(night, {"cutId": "c1"}, [], True, source="anime")  # noqa: SLF001
            # 작업 161: 기대값 변경 — 밤 문장도 낮 문장의 거울 꼴로 바꿨다(REAL_TIME_OF_DAY 가 {"day", "night"} 표가 됐다).
            expect("cs-c", [genmod._real_time_sentence(night), genmod.REAL_TIME_OF_DAY["night"] in kl_night,  # noqa: SLF001
                            genmod.REAL_TIME_OF_DAY["night"] in st_night, day in st_night],
                   ["Night, dark night sky, no daylight, no dusk, no sunset light.", True, True, False],
                   "밤 콘티 → 밤 문장(시작 그림·Kling)")
            report.append(f"edit {len(ra['edits'])}+{len(rb['edits'])}+{len(rc['edits'])}회(인물 2명 × 회차 3), "
                          f"원장 {len(ra['costumeLedger']) + len(rb['costumeLedger'])}줄, 저장 0, 컷 2 참고 {len(s2['refs'])}장")
            if llm_calls:
                bad.append(f"가짜가 아닌 LLM 호출: {llm_calls}")
    except Exception:  # noqa: BLE001
        bad.append("작업 160 검사 예외\n" + _tb.format_exc())
    if bad:
        fail("작업 160 장면 옷 1벌·장면 옷 참고·Kling 이어짐 검사 실패\n  " + "\n  ".join(bad))
    else:
        ok("작업 160 (cs-a)장소마다 옷 1벌(테이크·조각·155 고정·옛 경로·시작 그림, 다수결·동점·장소·콘티·수정) "
           "(cs-b)인물당 edit 1번·정면 자리·이름표·원장·저장 0·실패 → 지금 참고 (cs-c)앞 컷 시작 그림·시간대·넓히지 않기·밤")
        for line in report:
            print(f"       160: {line}")
# 작업 158: 기존 콘티 경로(CONTI_SYSTEM · _analyze_conti)를 가짜로 바꿔 끼우는 검사는 VNEW_VIBE_CONTI=False 로 부른다(기대값은 그대로).
