                with_costume = [member("범건우", [1, 2], sheet=1, costume_no=2), member("여의준", [3, 4], sheet=3, costume_no=4)]
                no_costume = [member("범건우", [1, 2], sheet=1), member("여의준", [3, 4], sheet=3)]
                sheet_only = [member("범건우", [1], sheet=1), member("여의준", [2], sheet=2)]
