                # ================= (fc-d) Kling @Element =================
                looks = {ids["범건우"]: _KP177_LOOK_A, ids["여의준"]: _KP177_LOOK_B}
                saved = {n: getattr(genmod, n) for n in ("_real_look", "_load_jpeg", "_fit_ref", "_costume_refs")}
